    ],
    marcas: [
      { id: 10, nombre: 'Samsung' },
      { id: 11, nombre: 'LG' }
    ]
  };

  // --- Variante Wizard ---
  wizardSteps: Step[] = [
    { label: 'Paso 1' },
    { label: 'Paso 2' },
    { label: 'Paso 3' }
  ];
  wizardActiveStep = signal(0);
}

