    const page = target.createElement('article');
    page.className = 'print-page';

    if (document.eyebrow) {
      page.append(this.textElement(target, 'p', document.eyebrow, 'eyebrow'));
    }
    page.append(this.textElement(target, 'h1', document.title));
    if (document.subtitle) {
