export interface ReceiptPanelField {
  readonly id: string;
  readonly label: string;
  readonly value: string;
  readonly emphasis?: boolean;
}

let receiptPanelSequence = 0;

const RECEIPT_PRINT_TOKENS = [
  '--receipt-paper-width',
  '--receipt-printable-width',
  '--receipt-print-padding',
  '--receipt-print-background',
  '--receipt-print-color',
  '--receipt-print-font-family',
  '--receipt-print-font-size',
  '--receipt-print-font-weight',
  '--receipt-print-letter-spacing',
  '--receipt-print-line-height',
] as const;

const RECEIPT_PRINT_STYLES = `
  @page {
    size: auto;
    margin: 0;
  }

  html,
  body {
    box-sizing: border-box;
    width: var(--receipt-paper-width, 58mm);
    min-width: var(--receipt-paper-width, 58mm);
    min-height: 0;
    margin: 0;
    padding: 0;
    overflow: visible;
    background: var(--receipt-print-background);
    color: var(--receipt-print-color);
  }

  body {
    padding-block: var(--receipt-print-padding, 1mm);
    padding-inline:
      calc(
        (
            var(--receipt-paper-width, 58mm) -
              var(--receipt-printable-width, 48mm)
          ) / 2
      );
  }

  pre {
    display: block;
    box-sizing: border-box;
    width: var(--receipt-printable-width, 48mm);
    margin: 0;
    overflow: visible;
    background: var(--receipt-print-background);
    color: var(--receipt-print-color);
    font-family: var(--receipt-print-font-family, 'Courier New', Courier, monospace);
    font-size: var(--receipt-print-font-size, 7pt);
    font-weight: var(--receipt-print-font-weight, 700);
    letter-spacing: var(--receipt-print-letter-spacing, 0);
    line-height: var(--receipt-print-line-height, 1.25);
    overflow-wrap: anywhere;
    white-space: pre-wrap;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
`;

/**
 * Organismo canónico para presentar e imprimir comprobantes térmicos.
 *
 * El contenido financiero permanece en el consumidor. Este componente aporta
 * la superficie responsive y crea un documento aislado de impresión de 58 mm.
 */
@Component({
  selector: 'app-receipt-panel, prest-receipt-panel',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  templateUrl: './receipt-panel.html',
  styleUrl: './receipt-panel.scss',
})
export class ReceiptPanel {
  readonly title = input('Comprobante');
  readonly titleId = input(`receipt-panel-title-${++receiptPanelSequence}`);
  readonly eyebrow = input('Operación confirmada');
  readonly subtitle = input('');
  readonly ariaLabel = input<string | null>(null);
  readonly formatLabel = input('Tiquetera térmica de 58 mm');
  readonly fields = input<readonly ReceiptPanelField[]>([]);
  readonly printText = input('');

  private readonly document = inject(DOCUMENT);
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);

  print(): boolean {
    const view = this.document.defaultView;
    const receiptText = this.printText();
    if (!view || receiptText.trim().length === 0) {
      return false;
    }

    const printWindow = view.open('', '_blank', 'popup=yes,width=420,height=640');
    if (!printWindow) {
      return false;
    }

    printWindow.opener = null;
    this.preparePrintDocument(printWindow, receiptText, view);

    const closePrintWindow = () => {
      printWindow.removeEventListener('afterprint', closePrintWindow);
      printWindow.close();
    };
    printWindow.addEventListener('afterprint', closePrintWindow, { once: true });

    printWindow.requestAnimationFrame(() => {
      printWindow.requestAnimationFrame(() => {
        if (printWindow.closed) {
          return;
        }

        try {
          void printWindow.document.body.offsetHeight;
          printWindow.focus();
          printWindow.print();
        } catch {
          closePrintWindow();
        }
      });
    });

    return true;
  }

  private preparePrintDocument(
    printWindow: Window,
    receiptText: string,
    sourceView: Window,
  ): void {
    const printDocument = printWindow.document;
    const sourceStyles = sourceView.getComputedStyle(this.host.nativeElement);

    printDocument.documentElement.lang = 'es';
    printDocument.title = this.title().trim() || 'Comprobante';

    for (const token of RECEIPT_PRINT_TOKENS) {
      const value = sourceStyles.getPropertyValue(token).trim();
      if (value) {
        printDocument.documentElement.style.setProperty(token, value);
      }
    }

    const charset = printDocument.createElement('meta');
    charset.setAttribute('charset', 'utf-8');

    const style = printDocument.createElement('style');
    style.textContent = RECEIPT_PRINT_STYLES;

    const receipt = printDocument.createElement('pre');
    receipt.textContent = receiptText;

    printDocument.head.replaceChildren(charset, style);
    printDocument.body.replaceChildren(receipt);
  }
}

export interface RectanguloSelect2 {
  readonly izquierda: number;
  readonly superior: number;
  readonly ancho: number;
  readonly alto: number;
}

export interface MedidasCapaSelect2 {
  readonly disparador: RectanguloSelect2;
  readonly ventana: RectanguloSelect2;
  readonly altoNatural: number;
  readonly margen: number;
  readonly separacion: number;
}

export interface PosicionCapaSelect2 {
  readonly izquierda: number;
  readonly superior: number;
  readonly ancho: number;
  readonly altoMaximo: number;
  readonly lado: 'arriba' | 'abajo';
}

/** Coordenadas de cliente; no se suma el desplazamiento del documento. */
export function calcularPosicionCapaSelect2(medidas: MedidasCapaSelect2): PosicionCapaSelect2 {
  const { disparador, ventana, altoNatural, margen, separacion } = medidas;
  const ancho = Math.max(0, Math.min(disparador.ancho, ventana.ancho - margen * 2));
  const izquierdaMinima = ventana.izquierda + margen;
  const izquierda = Math.max(izquierdaMinima,
    Math.min(disparador.izquierda, ventana.izquierda + ventana.ancho - margen - ancho));
  const superiorMinimo = ventana.superior + margen;
  const inferiorMaximo = ventana.superior + ventana.alto - margen;
  const inicioAbajo = disparador.superior + disparador.alto + separacion;
  const espacioAbajo = Math.max(0, inferiorMaximo - inicioAbajo);
  const espacioArriba = Math.max(0, disparador.superior - separacion - superiorMinimo);
  const lado = altoNatural <= espacioAbajo || espacioAbajo >= espacioArriba ? 'abajo' : 'arriba';
  const altoMaximo = Math.max(0, Math.min(altoNatural,
    lado === 'abajo' ? espacioAbajo : espacioArriba, ventana.alto - margen * 2));
  const superior = Math.max(superiorMinimo, Math.min(
    lado === 'abajo' ? inicioAbajo : disparador.superior - separacion - altoMaximo,
    inferiorMaximo - altoMaximo));
  return { izquierda, superior, ancho, altoMaximo, lado };
}

import { Injectable, inject, signal, computed } from '@angular/core';
import { Router } from '@angular/router';
import { Observable, of, throwError } from 'rxjs';
import { tap, catchError, switchMap } from 'rxjs/operators';

import { ApiService } from './api.service';
import { TokenService } from './token.service';

/**
 * User profile structure
 * @customize Adjust to match your API response
 */
export interface UserProfile {
    id: string | number;
    user: string;
    names: string;
    email?: string;
    role?: string;
    [key: string]: unknown;
}

/**
 * Login request structure
 * @customize Adjust to match your API
 */
export interface LoginRequest {
    v_user: string;
    v_password: string;
    v_ip?: string;
}

/**
 * Login response structure
 * @customize Adjust to match your API response
 */
export interface LoginResponse {
    access_Token: string;
    refresh_Token?: string;
    b_CAMBIO_CONTRASENIA?: boolean;
    user?: UserProfile;
}

/**
 * Refresh token request
 */
export interface RefreshTokenRequest {
    v_ACCESS_TOKEN: string;
    v_REFRESH_TOKEN: string;
}

/**
 * AuthService - Authentication management
 * 
 * Features:
 * - Login with username/password
 * - Automatic token refresh
 * - User profile management
 * - Logout and session cleanup
 * - Multi-app authentication support
 * 
 * @usage
 * ```typescript
 * // In component
 * private auth = inject(AuthService);
 * 
 * // Login
 * auth.login({ v_user: 'admin', v_password: '123' }).subscribe();
 * 
 * // Check auth state
 * if (auth.isAuthenticated()) { ... }
 * 
 * // Get current user
 * const user = auth.currentUser();
 * 
 * // Logout
 * auth.logout();
 * ```
 */
@Injectable({
    providedIn: 'root'
})
export class AuthService {
    private api = inject(ApiService);
    private tokenService = inject(TokenService);
    private router = inject(Router);

    // ============================================
    // CONFIGURATION - Customize these values
    // ============================================

    /** @customize Application ID for token storage */
    private appId = '2';

    /** @customize API endpoints */
    private readonly ENDPOINTS = {
        login: '/Authentication/PostLogin',
        profile: '/Authentication/Get_user_profile',
        refresh: '/Authentication/Post_refresh_token',
        changePassword: '/Authentication/Post_change_password'
    };

    /** @customize Route after logout */
    private readonly LOGIN_ROUTE = '/login';

    // ============================================
    // STATE
    // ============================================

    /** Current authenticated user */
    private _currentUser = signal<UserProfile | null>(null);

    /** Loading state */
    private _loading = signal(false);

    /** Error state */
    private _error = signal<string | null>(null);

    /** Password change required flag */
    private _requiresPasswordChange = signal(false);

    // ============================================
    // COMPUTED
    // ============================================

    /** Current user (readonly) */
    readonly currentUser = this._currentUser.asReadonly();

    /** Authentication status */
    readonly isAuthenticated = computed(() =>
        this.tokenService.hasValidToken(this.appId) && this._currentUser() !== null
    );

    /** Loading state */
    readonly loading = this._loading.asReadonly();

    /** Error message */
    readonly error = this._error.asReadonly();

    /** Password change required */
    readonly requiresPasswordChange = this._requiresPasswordChange.asReadonly();

    // ============================================
    // PUBLIC API
    // ============================================

    /**
     * Configure the app ID for multi-app environments
     * @param appId Application identifier
     */
    configure(appId: string): void {
        this.appId = appId;
        // Check if already authenticated
        if (this.tokenService.hasValidToken(appId)) {
            this.loadUserProfile().subscribe();
        }
    }

    /**
     * Login with credentials
     * @param credentials Login credentials
     * @returns Observable of login response
     */
    login(credentials: LoginRequest): Observable<LoginResponse> {
        this._loading.set(true);
        this._error.set(null);

        return this.api.post<LoginResponse>(this.ENDPOINTS.login, credentials).pipe(
            tap(response => {
                // Save tokens
                this.tokenService.saveTokenApp(response.access_Token, this.appId);

                if (response.refresh_Token) {
                    this.tokenService.saveRefreshToken(response.refresh_Token, this.appId);
                }

                // Check for password change requirement
                this._requiresPasswordChange.set(response.b_CAMBIO_CONTRASENIA ?? false);

                // Set user if included in response
                if (response.user) {
                    this._currentUser.set(response.user);
                }

                // Set auth header for future requests
                this.api.setAuthToken(response.access_Token);
            }),
            switchMap(response => {
                // Load full profile if not included
                if (!response.user) {
                    return this.loadUserProfile().pipe(
                        switchMap(() => of(response))
                    );
                }
                return of(response);
            }),
            tap(() => this._loading.set(false)),
            catchError(error => {
                this._loading.set(false);
                this._error.set(error.message || 'Error de autenticación');
                return throwError(() => error);
            })
        );
    }

    /**
     * Load user profile from API
     * @returns Observable of user profile
     */
    loadUserProfile(): Observable<UserProfile> {
        const userId = this.tokenService.getUserId(this.appId);

        return this.api.get<{ value: UserProfile }>(
            `${this.ENDPOINTS.profile}?I_ID_USER=${userId}`
        ).pipe(
            tap(response => {
                this._currentUser.set(response.value);
            }),
            switchMap(response => of(response.value))
        );
    }

    /**
     * Refresh access token using refresh token
     * @returns Observable of new login response
     */
    refreshToken(): Observable<LoginResponse> {
        const accessToken = this.tokenService.getTokenApp(this.appId);
        const refreshToken = this.tokenService.getRefreshToken(this.appId);

        if (!accessToken || !refreshToken) {
            return throwError(() => new Error('No tokens available'));
        }

        const request: RefreshTokenRequest = {
            v_ACCESS_TOKEN: accessToken,
            v_REFRESH_TOKEN: refreshToken
        };

        return this.api.post<LoginResponse>(this.ENDPOINTS.refresh, request).pipe(
            tap(response => {
                this.tokenService.saveTokenApp(response.access_Token, this.appId);

                if (response.refresh_Token) {
                    this.tokenService.saveRefreshToken(response.refresh_Token, this.appId);
                }

                this.api.setAuthToken(response.access_Token);
            }),
            catchError(error => {
                // If refresh fails, force logout
                this.logout();
                return throwError(() => error);
            })
        );
    }

    /**
     * Logout and clear all session data
     * @param redirect Whether to redirect to login page (default: true)
     */
    logout(redirect = true): void {
        this.tokenService.removeTokenApp(this.appId);
        this._currentUser.set(null);
        this._error.set(null);
        this.api.setAuthToken('');

        if (redirect) {
            this.router.navigate([this.LOGIN_ROUTE]);
        }
    }

    /**
     * Check if current token is about to expire
     * @returns true if token expires within 5 minutes
     */
    isTokenExpiring(): boolean {
        const token = this.tokenService.getTokenApp(this.appId);
        if (!token) return true;

        return this.tokenService.isTokenExpired(token, 5 * 60 * 1000);
    }

    /**
     * Get current access token
     * @returns Current token or null
     */
    getToken(): string | null {
        return this.tokenService.getTokenApp(this.appId);
    }

    /**
     * Clear error state
     */
    clearError(): void {
        this._error.set(null);
    }
}

import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';

