      '--select2-capa-izquierda': posicion ? `${posicion.izquierda}px` : null,
      '--select2-capa-superior': posicion ? `${posicion.superior}px` : null,
      '--select2-capa-ancho': posicion ? `${posicion.ancho}px` : null,
