          rectangulo && rectangulo.width > 0 && rectangulo.height > 0 &&
          estilo?.display !== 'none' && estilo?.visibility !== 'hidden' && estilo?.visibility !== 'collapse') {
        buscador.focus({ preventScroll: true });
