          this.enfocarBusquedaPendiente = false;
        }
      }
      if (reintentos > 0 && (this.enfocarBusquedaPendiente || this.desplazamientoInicialPendiente)) {
        this.programarFocoBusqueda(reintentos - 1);
      }
