    const ancho = this.width().trim();
    return ancho.length > 0 && !ancho.includes('%');
  });

  hasValue(): boolean {
    return this.multiple() ? this.selectedOptions().length > 0 : this.selectedOption() !== null;
  }

  filteredOptions(): readonly Select2Option[] {
    const term = this.searchTerm().toLowerCase();
    if (!term) return this.options;
    return this.options.filter(o => o.label.toLowerCase().includes(term));
  }

  isSelected(option: Select2Option): boolean {
    if (option.value === null || option.value === '') {
      return false;
    }
    if (this.multiple()) {
      return this.selectedOptions().some(o => o.value === option.value);
    }
    return this.selectedOption()?.value === option.value;
  }

  toggleDropdown(): void {
    if (this.disabled) return;
    if (this.isOpen()) this.cerrarDesplegable(false, true);
    else {
      this.isOpen.set(true);
      this.ensureEnabledHighlight();
    }
  }

  handleKeydown(event: KeyboardEvent): void {
    if (this.disabled) return;

    const options = this.filteredOptions();
    const isSearchInput = (event.target as HTMLElement | null)?.classList.contains('search-input');

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        if (!this.isOpen()) {
          this.toggleDropdown();
        } else {
          this.highlightedIndex.set(this.nextEnabledIndex(options, this.highlightedIndex(), 1));
          this.scrollToHighlighted();
        }
        break;
      case 'ArrowUp':
        event.preventDefault();
        if (!this.isOpen()) {
          this.toggleDropdown();
        } else {
          this.highlightedIndex.set(this.nextEnabledIndex(options, this.highlightedIndex(), -1));
          this.scrollToHighlighted();
        }
        break;
      case 'Enter':
      case ' ':
        if (event.key === ' ' && isSearchInput) return;
        event.preventDefault();
        if (!this.isOpen()) {
          this.toggleDropdown();
        } else if (this.highlightedIndex() >= 0) {
          const option = options[this.highlightedIndex()];
          if (option && !option.disabled) {
            this.selectOption(option);
          }
        }
        break;
      case 'Escape':
        if (this.isOpen()) {
          event.preventDefault();
          event.stopPropagation();
          this.cerrarDesplegable(true, true);
        }
        break;
      case 'Tab':
        if (this.isOpen()) {
          this.programarCierrePorTab(event);
        }
        break;
    }
  }

  private scrollToHighlighted(): void {
    const listbox = this.panelActivo?.querySelector<HTMLElement>('.select2-options');
    const highlighted = listbox?.querySelectorAll<HTMLElement>('.select2-option')[this.highlightedIndex()];
    if (highlighted && listbox) {
      const caja = listbox.getBoundingClientRect();
      const opcion = highlighted.getBoundingClientRect();
      if (opcion.top < caja.top) listbox.scrollTop -= caja.top - opcion.top;
      else if (opcion.bottom > caja.bottom) listbox.scrollTop += opcion.bottom - caja.bottom;
    }
  }

  selectOption(option: Select2Option): void {
    if (this.disabled || option.disabled) return;
    this.pendingValue = undefined;
    if (this.multiple()) {
      const current = this.selectedOptions();
      if (this.isSelected(option)) {
        this.selectedOptions.set(current.filter(o => o.value !== option.value));
      } else if (option.value !== null && option.value !== '') {
        this.selectedOptions.set([...current, option]);
      }
      const values = this.selectedOptions().map(o => o.value);
      this.onChange(values);
      this.valueChange.emit(values);
      this.onTouched();
      this.programarPosicionCapa();
    } else {
      this.selectedOption.set(option.value === null || option.value === '' ? null : option);
      this.onChange(option.value);
      this.valueChange.emit(option.value);

      this.cerrarDesplegable(true, false);
      this.onTouched();
    }
  }

  removeTag(option: Select2Option, event: Event): void {
    event.stopPropagation();
    if (this.disabled) return;
    this.pendingValue = undefined;
    const current = this.selectedOptions();
    this.selectedOptions.set(current.filter(o => o.value !== option.value));
    const values = this.selectedOptions().map(o => o.value);
    this.onChange(values);
    this.valueChange.emit(values);
    this.onTouched();
    this.programarPosicionCapa();
  }

  @HostListener('document:click', ['$event'])
  onClickOutside(event: Event): void {
    if (!this.elementRef.nativeElement.contains(event.target)) {
      if (this.isOpen()) {
        this.cerrarDesplegable(false, true);
      }
    }
  }

  writeValue(value: unknown): void {
    this.pendingValue = value;
    if (!this.options.length) {
      // Guarda el valor hasta que lleguen las opciones (carga asíncrona)
      this.clearSelection();
      return;
    }
    this.applyIncomingValue(value);
  }

  registerOnChange(fn: (value: unknown) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }

  onSearchTermChange(value: string): void {
    this.searchTerm.set(value);
    this.highlightedIndex.set(this.nextEnabledIndex(this.filteredOptions(), -1, 1));
    this.programarPosicionCapa();
  }

  removeTagLabel(option: Select2Option): string {
    return `Quitar ${option.label}`;
  }

  /** Limpia selecciones actuales */
  private clearSelection(): void {
    this.selectedOption.set(null);
    this.selectedOptions.set([]);
  }

  /** Aplica un valor entrante respetando los modos single/multiple */
  private applyIncomingValue(value: unknown, emit = false): void {
    if (this.multiple()) {
      const values = Array.isArray(value) ? value as (string | number)[] : [];
      const validOptions = this.options.filter(o => o.value !== null && o.value !== '' && values.includes(o.value as string | number));
      this.selectedOptions.set(validOptions);
      if (validOptions.length > 0 || values.length === 0) {
        this.pendingValue = undefined;
      }
      if (emit) {
        this.onChange(validOptions.map(o => o.value));
        this.valueChange.emit(validOptions.map(o => o.value));
      }
    } else {
      const isEmpty = value === null || value === undefined || value === '';
      const option = !isEmpty ? this.options.find(o => o.value === value) : undefined;
      this.selectedOption.set(option || null);
      if (isEmpty || option) {
        this.pendingValue = undefined;
      }
      if (emit && option) {
        this.onChange(option.value);
        this.valueChange.emit(option.value);
      }
    }
  }

  /** Rehidrata selección cuando cambian las opciones */
  private reconcilePendingValue(): void {
    if (this.pendingValue !== undefined) {
      this.applyIncomingValue(this.pendingValue);
      this.pendingValue = undefined;
      return;
    }

    // Revalida selección actual por si alguna opción desapareció
    if (this.multiple()) {
      const currentValues = this.selectedOptions().map(o => o.value);
      this.applyIncomingValue(currentValues);
    } else {
      this.applyIncomingValue(this.selectedOption()?.value);
    }
  }

  private ensureEnabledHighlight(): void {
    if (!this.isOpen()) return;
    const options = this.filteredOptions();
    const current = this.highlightedIndex();
    if (current >= 0 && options[current] && !options[current].disabled) return;

    const selectedValue = !this.multiple() ? this.selectedOption()?.value : undefined;
    const selected = options.findIndex(option => option.value === selectedValue && !option.disabled);
    this.highlightedIndex.set(selected >= 0 ? selected : this.nextEnabledIndex(options, -1, 1));
  }

  private nextEnabledIndex(
    options: readonly Select2Option[],
    current: number,
    direction: 1 | -1
  ): number {
    let index = current;
    if (index < 0) index = direction === 1 ? -1 : options.length;
    for (index += direction; index >= 0 && index < options.length; index += direction) {
      if (!options[index].disabled) return index;
    }
    return current >= 0 && options[current] && !options[current].disabled ? current : -1;
  }
}

import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  afterRenderEffect,
  computed,
  forwardRef,
  inject,
  input,
  output,
  signal,
  viewChild,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import {
  FIELD_LABEL_VARIANT_DEFAULT,
  FieldLabelVariant,
  esEtiquetaElevada,
  esEtiquetaFlotante,
} from '../form-field/field-label';
import { FormErrorComponent } from '../form-error/form-error.component';

export interface SelectOption {
  readonly value: string | number;
  readonly label: string;
  readonly disabled?: boolean;
}

/**
 * Seleccion canonica de Atomic UI (`SelectComponent`).
 *
 * Unifica `atoms/select` y `atoms/form-select`: conserva los selectores `app-select`,
 * `prest-select` y `app-form-select`; el alias `Select` se mantiene exportado desde
 * `atoms/form-select/select`.
 *
 * `variant` sigue el contrato comun de etiqueta (`standard` | `floating` | `floating-value`).
 * Un `<select>` nativo siempre muestra el texto de la opcion elegida; con etiqueta flotante en
 * reposo, ese texto (marcador) se hace transparente para no superponerse a la etiqueta.
 */
@Component({
  selector: 'app-select, prest-select, app-form-select',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [TranslateModule, FormErrorComponent],
  templateUrl: './select.component.html',
  styleUrls: ['./select.component.css', '../form-field/field-label.css'],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => SelectComponent),
      multi: true,
    },
  ],
})
export class SelectComponent implements ControlValueAccessor {
  private static nextId = 0;
  private readonly changeDetector = inject(ChangeDetectorRef);
  private readonly generatedId = `prest-select-${++SelectComponent.nextId}`;

  readonly options = input<readonly SelectOption[]>([]);
  readonly selected = input<string | number | null>(null);
  readonly label = input('');
  readonly variant = input<FieldLabelVariant>(FIELD_LABEL_VARIANT_DEFAULT);
  readonly ariaLabel = input<string | null>(null);
  readonly placeholder = input('Seleccione');
  readonly error = input<string | null>(null);
  readonly hint = input<string | null>(null);
  readonly disabled = input(false);
  readonly required = input(false);
  readonly controlId = input<string | null>(null);

  readonly selectionChange = output<string>();

  private readonly nativeSelect = viewChild<ElementRef<HTMLSelectElement>>('nativeSelect');

  constructor() {
    /*
    RECHAZAR UNA ELECCION TAMBIEN TIENE QUE RETIRARLA DE LA PANTALLA.

    En modo gobernado —`[selected]` atado a una señal del padre mas
    `(selectionChange)`— `value()` ignora `formValue()` mientras `selected()` no
    sea nulo. Si el padre rechaza lo elegido y deja su señal como estaba,
    `value()` devuelve lo mismo que antes, las expresiones `[selected]` de las
    `<option>` no cambian, Angular no escribe nada, y el `<select>` se queda
    mostrando la opcion que marco el navegador con el clic.

    Lo que se ve deja de ser lo que se envia, y desde el consumidor no hay forma
    de arreglarlo: es la causa raiz de los rechazos mudos de pantalla.

    El efecto SI se vuelve a ejecutar aunque `selected()` no cambie, porque
    `handleChange` escribe `formValue` en cada interaccion. Es el mismo patron
    «señal gobernada + effect» que ya usa `file-input`.
    */
    afterRenderEffect(() => {
      const esperado = this.value();
      // Dependencia explicita: sin leerla, una eleccion rechazada dos veces
      // seguidas no volveria a disparar el efecto.
      this.formValue();
      const element = this.nativeSelect()?.nativeElement;
      if (element && element.value !== esperado) {
        element.value = esperado;
      }
    });
  }

  protected readonly formValue = signal('');
  protected readonly enfocado = signal(false);
  protected readonly controlDisabled = signal(false);
  protected readonly id = computed(() => this.controlId() ?? this.generatedId);
  protected readonly effectiveDisabled = computed(() => this.disabled() || this.controlDisabled());
  protected readonly value = computed(() => {
    const selected = this.selected();
    return selected == null ? this.formValue() : String(selected);
  });
  protected readonly legacyOption = computed<SelectOption | null>(() => {
    const value = this.value();
    if (!value || this.options().some((option) => String(option.value) === value)) {
      return null;
    }
    return { value, label: value };
  });

  protected readonly tieneEtiqueta = computed(() => this.label().length > 0);
  protected readonly flotante = computed(() =>
    esEtiquetaFlotante(this.variant(), this.tieneEtiqueta()),
  );
  protected readonly elevada = computed(() =>
    esEtiquetaElevada(this.variant(), this.tieneEtiqueta(), this.enfocado(), this.value() !== ''),
  );
  /** Etiqueta flotante en reposo y sin valor: el texto del marcador se oculta (no se superpone). */
  protected readonly marcadorOculto = computed(() => this.flotante() && !this.elevada());
  protected readonly descritoPor = computed(() => {
    if (this.error()) return `${this.id()}-error`;
    if (this.hint()) return `${this.id()}-hint`;
    return null;
  });

  private onChange: (value: unknown) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  /** Compatibilidad con el `SelectComponent` historico. */
  get selectId(): string {
    return this.id();
  }

  /** Compatibilidad con el `SelectComponent` historico. */
  isDisabled(): boolean {
    return this.effectiveDisabled();
  }

  protected handleChange(event: Event): void {
    const value = (event.target as HTMLSelectElement).value;
    const selectedOption = this.options().find((option) => String(option.value) === value);
    this.formValue.set(value);
    this.onChange(selectedOption?.value ?? value);
    this.selectionChange.emit(value);
  }

  protected handleFocus(): void {
    this.enfocado.set(true);
  }

  protected handleBlur(): void {
    this.enfocado.set(false);
    this.onTouched();
  }

  writeValue(value: unknown): void {
    this.formValue.set(value == null ? '' : String(value));
    this.changeDetector.markForCheck();
  }

  registerOnChange(fn: (value: unknown) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(disabled: boolean): void {
    this.controlDisabled.set(disabled);
    this.changeDetector.markForCheck();
  }
}

import {
  Component,
  ElementRef,
  inject,
  PLATFORM_ID,
  input,
  output
} from '@angular/core';
import { isPlatformBrowser, NgTemplateOutlet } from '@angular/common';
import { AvatarComponent } from '../../atoms/avatar/avatar.component';
import { ScrollOverlayComponent } from '../scroll-overlay/scroll-overlay.component';
import { VariablesCssDirective } from '../../directives/variables-css.directive';
import { TooltipDirective } from '../../atoms/tooltip/tooltip.directive';

export interface SidebarMenuItem {
  id?: string;
  label: string;
  icon: string;
  iconColor?: string;
  active?: boolean;
  route?: string;
  badge?: string | number;
  children?: SidebarMenuItem[];
  expanded?: boolean;
  separator?: boolean;
}

export interface SidebarUser {
  name: string;
  role: string;
  initials?: string;
  photo?: string;
  avatarColor?: string;
}

@Component({
  selector: 'app-sidebar',
  standalone: true,
  imports: [AvatarComponent, NgTemplateOutlet, ScrollOverlayComponent, VariablesCssDirective, TooltipDirective],
  templateUrl: './sidebar.component.html',
  styleUrl: './sidebar.component.css',
})
export class SidebarComponent {
  private readonly platformId = inject(PLATFORM_ID);
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);

  /** Menu items to display */
  readonly menuItems = input<SidebarMenuItem[]>([]);

  /** Current user information */
  readonly user = input<SidebarUser | null>();

  /** Check if the sidebar is expanded (visual mode) */
  readonly collapsed = input(false);

  /** Logo text */
  readonly logoText = input('Atomic UI');

  /** Logo icon */
  readonly logoIcon = input('fa-solid fa-atom');

  /** Logo icon color */
  readonly logoIconColor = input<string>();

  /** Logo text color */
  readonly logoTextColor = input<string>();

  /** Background color for the header (logo area) */
  readonly headerBgColor = input<string>();

  /** Background color for the footer (user area) */
  readonly footerBgColor = input<string>();

  /** Event emitted when a menu item is clicked */
  readonly navigate = output<SidebarMenuItem>();

  private readonly expansionOverrides = new Map<string, boolean>();

  onItemClick(item: SidebarMenuItem): void {
    if (this.hasChildren(item)) {
      this.expansionOverrides.set(this.itemKey(item), !this.isExpanded(item));
      return;
    }
    this.navigate.emit(item);
  }

  hasChildren(item: SidebarMenuItem): boolean {
    return (item.children?.length ?? 0) > 0;
  }

  isExpanded(item: SidebarMenuItem): boolean {
    const override = this.expansionOverrides.get(this.itemKey(item));
    if (override !== undefined) {
      return override;
    }
    return item.expanded ?? this.containsActiveItem(item);
  }

  itemKey(item: SidebarMenuItem): string {
    return item.id ?? item.route ?? item.label;
  }

  handleKeydown(event: KeyboardEvent): void {
    if (!isPlatformBrowser(this.platformId)) return;

    const items = Array.from(
      this.host.nativeElement.querySelectorAll<HTMLElement>('.sidebar-nav .nav-link'),
    );
    if (!items.length) return;

    const activeIndex = Math.max(
      items.indexOf(this.host.nativeElement.ownerDocument.activeElement as HTMLElement),
      0,
    );
    let nextIndex: number | undefined;

    switch (event.key) {
      case 'ArrowDown':
        nextIndex = (activeIndex + 1) % items.length;
        break;
      case 'ArrowUp':
        nextIndex = (activeIndex - 1 + items.length) % items.length;
        break;
      case 'Home':
        nextIndex = 0;
        break;
      case 'End':
        nextIndex = items.length - 1;
        break;
    }

    if (nextIndex !== undefined) {
      items[nextIndex]?.focus();
      event.preventDefault();
    }
  }

  private containsActiveItem(item: SidebarMenuItem): boolean {
    return !!item.active || !!item.children?.some((child) => this.containsActiveItem(child));
  }
}

