import { ChangeDetectionStrategy, Component, inject, input } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { VersionComponent } from '../../atoms/version/version.component';
import { LinkComponent } from '../../atoms/link/link.component';
import { AppVersionService } from '../../services/app-version.service';

export interface SocialLink {
  platform: 'facebook' | 'twitter' | 'instagram' | 'linkedin' | 'github' | 'youtube';
  url: string;
  label?: string;
}

export interface LegalLink {
  label: string;
  url: string;
}

export type FooterVariant = 'simple' | 'inline' | 'columns';

/**
 * Pie de página genérico del sistema Atomic.
 *
 * El componente no depende de un proveedor de traducciones. El shell es quien
 * reserva su fila al final de la ventana; el footer sólo controla su contenido
 * y presentación para no competir con el contenedor que posee el scroll.
 */
@Component({
  selector: 'app-footer',
  standalone: true,
  imports: [NgTemplateOutlet, VersionComponent, LinkComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './footer.component.css',
    templateUrl: './footer.component.html'
})
export class FooterComponent {
  public readonly versionService = inject(AppVersionService, { optional: true });

  readonly variant = input<FooterVariant>('inline');
  readonly accessibleLabel = input('Pie de página');
  readonly companyName = input('Suite Barracuda');
  readonly year = input(new Date().getFullYear());
  readonly copyrightText = input('Todos los derechos reservados.');
  readonly copyrightSeparator = input(' - ');
  readonly supportText = input('');
  readonly supportSeparator = input('|');
  readonly description = input('');
  readonly legalTitle = input('Enlaces legales');
  readonly socialTitle = input('Redes sociales');
  readonly showVersion = input(true);
  readonly showBuildDate = input(false);
  readonly version = input('v1.0.0');
  readonly environment = input('PROD');
  readonly buildDate = input('');
  readonly socialLinks = input<SocialLink[]>([]);
  readonly legalLinks = input<LegalLink[]>([]);

  get copyrightLine(): string {
    return `© ${this.year()} ${this.companyName()}${this.copyrightSeparator()}${this.copyrightText()}`;
  }

  getSocialIcon(platform: SocialLink['platform']): string {
    const icons: Record<SocialLink['platform'], string> = {
      facebook: 'fa-brands fa-facebook-f',
      twitter: 'fa-brands fa-x-twitter',
      instagram: 'fa-brands fa-instagram',
      linkedin: 'fa-brands fa-linkedin-in',
      github: 'fa-brands fa-github',
      youtube: 'fa-brands fa-youtube'
    };
    return icons[platform];
  }

  getSocialLabel(link: SocialLink): string {
    if (link.label) return link.label;
    const labels: Record<SocialLink['platform'], string> = {
      facebook: 'Facebook',
      twitter: 'X',
      instagram: 'Instagram',
      linkedin: 'LinkedIn',
      github: 'GitHub',
      youtube: 'YouTube'
    };
    return labels[link.platform];
  }
}

export interface PaginaDto<T> {
  readonly elementos: readonly T[];
  readonly pagina: number;
  readonly tamano: number;
  readonly total: number;
}

/** Parámetros que emite el chasis cuando la tabla necesita datos nuevos. */
export interface SolicitudPagina {
  readonly pagina: number;
  readonly tamano: number;
  readonly busqueda: string;
}

// ============================================================
// MODOS CRUD
// ============================================================

/** Los tres modos que soporta el diálogo CRUD (Doctrina ADR-007). */
export type ModoCrud = 'crear' | 'editar' | 'ver';

/** Contexto que el chasis pasa a la plantilla del formulario proyectado. */
export interface ContextoFormularioCrud<T> {
  /** Referencia implícita para `let-entidad` en la plantilla. */
  readonly $implicit: T | null;
  /** La entidad activa (null en modo crear). */
  readonly entidad: T | null;
  /** Modo actual del diálogo. */
  readonly modo: ModoCrud;
  /** Indica si la operación de guardado está en curso. */
  readonly guardando: boolean;
}

// ============================================================
// CONFIGURACIÓN DE ENTIDAD (para accordion multi-entidad)
// ============================================================

/**
 * Define una entidad dentro de un acordeón CRUD.
 * Cada entrada genera un accordion-item con su propia grilla y diálogo.
 */
export interface EntidadAccordion<_T extends object = Record<string, unknown>> {
  /** Identificador único de la entidad dentro del acordeón. */
  readonly clave: string;
  /** Título visible en la cabecera del accordion-item. */
  readonly titulo: string;
  /** Descripción opcional debajo del título. */
  readonly descripcion?: string;
  /** Icono Font Awesome opcional para la cabecera del panel. */
  readonly icono?: string;
  /** Si el item arranca abierto (solo el principal). */
  readonly abiertoInicial?: boolean;
  /** Si el panel de la entidad está temporalmente deshabilitado. */
  readonly deshabilitada?: boolean;
  /** Etiqueta del botón de acción principal. Por defecto 'Nuevo'. */
  readonly etiquetaNuevo?: string;
  /** Placeholder del campo de búsqueda. */
  readonly placeholderBusqueda?: string;
  /** Título del diálogo CRUD según el modo. */
  readonly titulosDialogo?: Partial<Record<ModoCrud, string>>;
  /** Tamaño del diálogo. Por defecto 'md'. */
  readonly tamanoDialogo?: 'sm' | 'md' | 'lg' | 'xl';
}

// ============================================================
// ACCIONES DE FILA
// ============================================================

/**
 * Acciones estándar disponibles en la columna de acciones de la grilla.
 * Corresponden directamente a los valores de TableActionName de Atomic.
 *
 * Por defecto el chasis habilita: ver, editar, eliminar (Doctrina ADR-007).
 */
export interface AccionesCrud {
  /** Mostrar botón de previsualización (ojo). Por defecto: true. */
  readonly ver?: boolean;
  /** Mostrar botón de edición (lápiz). Por defecto: true. */
  readonly editar?: boolean;
  /** Mostrar botón de eliminación/baja (papelera). Por defecto: true. */
  readonly eliminar?: boolean;
}

/**
 * Justificación auditable para una tercera acción directa de catálogo.
 *
 * El estándar físico conserva Ver, Editar y Más acciones. Una acción
 * contextual solo puede ocupar un tercer botón directo cuando el consumidor
 * declara por qué es frecuente y cuál es la evidencia que sostiene esa
 * excepción. Atomic solo valida la declaración y la semántica visual; no
 * infiere permisos, contratos ni frecuencia real.
 */
export interface AccionDirectaContextualCatalogo {
  /** Id de una acción ya declarada por fila. */
  readonly idAccion: string;
  /** Razón concreta por la que la acción debe permanecer a la vista. */
  readonly justificacion: string;
  /** Evidencia verificable de uso frecuente o necesidad operacional. */
  readonly evidencia: string;
}

/** Acciones por defecto que el chasis utiliza si no se sobreescriben. */
export const ACCIONES_CRUD_DEFECTO: Readonly<Required<AccionesCrud>> = {
  ver: true,
  editar: true,
  eliminar: true,
} as const;

// ============================================================
// CONFIRMACIÓN DE BAJA
// ============================================================

/**
 * Configuración del diálogo de confirmación de baja lógica.
 * Cumple Doctrina de Interfaz §7 y §12:
 *   - El mensaje enumera qué va a cambiar con nombres concretos.
 *   - El botón lleva el verbo del acto ('Desactivar').
 *   - El foco inicial se pone en cancelar.
 */
export interface ConfiguracionConfirmacion {
