  ];

  private nombres = [
    'Juan Pérez', 'María García', 'Carlos López', 'Ana Martínez',
    'Pedro Sánchez', 'Laura Torres', 'Diego Ramírez', 'Sofia Herrera',
  ];
  private estados = [
    'data.status.active', 'data.status.pending', 'data.status.completed',
    'data.status.review', 'data.status.approved',
  ];
  private tipos = [
    'data.type.invoice', 'data.type.receipt', 'data.type.order',
    'data.type.quote', 'data.type.contract',
  ];
  private prioridades = ['data.priority.high', 'data.priority.medium', 'data.priority.low'];

  rowCount = signal(25);
  private allTableData: TableRow[] = [];
  protected readonly tableData = signal<TableRow[]>([]);

  protected readonly tableColumns = computed<DataTableColumn<TableRow>[]>(() => [
    { key: 'col1', header: 'table.headers.id', align: 'center', width: '70px', sortable: true },
    { key: 'col2', header: 'table.headers.name', width: 'minmax(150px, 1fr)', sortable: true },
    { key: 'col3', header: 'table.headers.email', width: 'minmax(220px, 1.5fr)', sortable: true },
    { key: 'col4', header: 'table.headers.date', width: '100px', sortable: true },
    { 
      key: 'col5', 
      header: 'table.headers.status', 
      align: 'center', 
      width: '130px', 
      isTag: true, 
      tagVariant: (row: TableRow) => this.getTagVariantForTable(row.statusVariant),
      format: (val) => this.translate.instant(val as string)
    },
    { key: 'col6', header: 'table.headers.type', width: '175px', sortable: true, format: (val) => this.translate.instant(val as string) },
    { key: 'col7', header: 'table.headers.amount', width: '90px', sortable: true },
    { key: 'col8', header: 'table.headers.priority', align: 'center', width: '110px', sortable: true, format: (val) => this.translate.instant(val as string) },
  ]);

  private getTagVariantForTable(variant: string): ChipVariant {
    switch (variant) {
      case 'success':
      case 'primary':
        return 'success';
      case 'warning':
      case 'secondary':
        return 'warning';
      case 'error':
        return 'error';
      default:
        return 'default';
    }
  }


  updateRowCount(count: string | number) {
    const value = Number(count);
    if (!isNaN(value) && value > 0) {
      this.rowCount.set(value);
      this.generateData();
    }
  }

  private generateData() {
    const count = this.rowCount();
    this.allTableData = Array.from({ length: count }, (_, i) => {
      const nombre = this.nombres[i % this.nombres.length];
      const email =
        nombre
          .toLowerCase()
          .replace(' ', '.')
          .replace(/á/g, 'a').replace(/é/g, 'e').replace(/í/g, 'i')
          .replace(/ó/g, 'o').replace(/ú/g, 'u') + '@email.com';
      const statusKey = this.estados[i % this.estados.length];
      return {
        col1: `${1001 + i}`,
        col2: nombre,
        col3: email,
        col4: `${String(Math.floor(Math.random() * 28) + 1).padStart(2, '0')}/12/2024`,
        col5: statusKey,
        col6: this.tipos[i % this.tipos.length],
        col7: `S/ ${(Math.random() * 500 + 50).toFixed(2)}`,
        col8: this.prioridades[i % this.prioridades.length],
        statusVariant: this.getStatusClass(statusKey),
      };
    });
    this.tableData.set(this.allTableData);
  }
}

import {
