  animation: menuFadeIn 150ms ease;
  display: flex;
  flex-direction: column;
}

@keyframes menuFadeIn {
  from { opacity: 0; transform: translateY(calc(-1 * var(--space-1))); }
  to { opacity: 1; transform: translateY(0); }
}

.menu-item {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  width: 100%;
  padding: var(--space-2) var(--space-3);
