  color: var(--text-color);
  overflow: hidden;
  flex-shrink: 0;
  aspect-ratio: 1;
}

.avatar-rounded {
  border-radius: var(--radius-md);
}

/* Variants */
.avatar-primary { background-color: var(--avatar-background-color, var(--primary-color-lighter)); color: var(--primary-color); }
.avatar-secondary { background-color: var(--avatar-background-color, var(--secondary-color-lighter)); color: var(--secondary-color); }
.avatar-success { background-color: var(--avatar-background-color, var(--success-color-lighter)); color: var(--success-color-text); }
.avatar-warning { background-color: var(--avatar-background-color, var(--warning-color-lighter)); color: var(--warning-color-text); }
.avatar-danger { background-color: var(--avatar-background-color, var(--danger-color-lighter)); color: var(--danger-color-text); }
.avatar-info { background-color: var(--avatar-background-color, var(--info-color-lighter)); color: var(--info-color-text); }
.avatar-user { background: linear-gradient(135deg, var(--primary-color), var(--primary-color-dark)) !important; color: var(--text-color-on-primary) !important; }

.avatar-xs { width: var(--avatar-xs); height: var(--avatar-xs); font-size: var(--text-xs); }
.avatar-sm { width: var(--avatar-sm); height: var(--avatar-sm); font-size: var(--text-xs); }
.avatar-md { width: var(--avatar-md); height: var(--avatar-md); font-size: var(--text-sm); }
.avatar-lg { width: var(--avatar-lg); height: var(--avatar-lg); font-size: var(--text-lg); }
.avatar-xl { width: var(--avatar-xl); height: var(--avatar-xl); font-size: var(--text-xl); }

.avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.avatar i {
  font-size: 1.2em;
}

.avatar-initials {
  font-weight: var(--font-weight-emphasis);
  text-transform: uppercase;
  color: var(--text-color-on-primary);
}

/* Ensure initials in colored variants contrast well (usually dark on light bg or vice versa) */
.avatar:not(.avatar-default) .avatar-initials {
   color: currentColor;
}

.avatar-placeholder {
  width: 60%;
  height: 60%;
  color: var(--text-color-muted);
}

.avatar-placeholder svg {
  width: 100%;
  height: 100%;
}

.avatar-status {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 25%;
  height: 25%;
  min-width: var(--space-2);
  min-height: var(--space-2);
  border-radius: var(--radius-full);
  border: var(--space-1) solid var(--surface-background);
}

.status-online { background: var(--success-color); }
.status-offline { background: var(--text-color-secondary); }
.status-busy { background: var(--danger-color); }
.status-away { background: var(--warning-color); }

/* Dark mode */
:host-context(html.dark) .avatar-default,
:host-context([data-theme="dark"]) .avatar-default {
  background: var(--avatar-background-color, var(--surface-section));
}

:host-context(html.dark) .avatar-status,
:host-context([data-theme="dark"]) .avatar-status {
  border-color: var(--surface-section);
}

