:host {
  display: contents;
}

.context-menu {
  position: fixed;
  left: var(--context-menu-left, 0);
  top: var(--context-menu-top, 0);
  z-index: 100000;
  display: flex;
  flex-direction: column;
  min-width: calc(var(--space-10) + var(--space-10) + var(--space-10));
  max-width: calc(100vw - var(--space-4));
  max-height: calc(100vh - var(--space-4));
  padding: var(--space-1);
  overflow: auto;
  color: var(--text-color);
  background: var(--dropdown-bg);
  border: var(--border-width-thin) solid var(--dropdown-border);
  border-radius: var(--radius-md);
  /*
    `--dropdown-shadow` era un alias puro de `--shadow-dropdown` en los tres
    temas -sin una sola divergencia-, asi que resolverlo no pierde ningun gancho
    de tema y si gana la escala: `--shadow-lg` es el peldano de menu y popover, y
    en oscuro trae el anillo de 1px sin el que este panel no se despegaba del
    fondo.
  */
  box-shadow: var(--shadow-lg);
}

.context-menu__item {
  display: grid;
  grid-template-columns: var(--space-5) minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--space-2);
  width: 100%;
  min-height: var(--control-height-sm);
  padding: var(--space-2) var(--space-3);
  color: var(--text-color);
  font: inherit;
  font-size: var(--text-sm);
  text-align: left;
  white-space: nowrap;
  background: transparent;
  border: 0;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.context-menu__item:hover:not(:disabled),
.context-menu__item:focus-visible,
.context-menu__item--active:not(:disabled) {
  color: var(--text-color);
  background: var(--dropdown-item-hover);
  outline: none;
}

.context-menu__item:focus-visible {
  box-shadow: var(--focus-ring);
}

.context-menu__item:disabled {
  color: var(--input-disabled-text);
  cursor: not-allowed;
}

.context-menu__icon {
  width: var(--space-5);
  color: currentColor;
  text-align: center;
}

.context-menu__label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.context-menu__shortcut {
  margin-left: var(--space-3);
  color: var(--text-color-muted);
  font-size: var(--text-xs);
}

.context-menu__feedback {
  position: absolute;
  inline-size: var(--border-width-thin);
  block-size: var(--border-width-thin);
  padding: 0;
  margin: calc(-1 * var(--border-width-thin));
  overflow: hidden;
  white-space: nowrap;
  border: 0;
  clip-path: inset(50%);
}

