:host {
  display: block;
  min-width: 0;
  max-width: 100%;
}

.data-table__region {
  display: block;
  max-width: 100%;
  overflow: hidden;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--surface-background);
  box-shadow: var(--shadow-sm);
}

.data-table__viewport {
  display: flex;
  flex-direction: column;
  height: auto;
  min-height: 18rem;
  max-height: 55rem;
  overflow: hidden;
  background: var(--surface-background);

  ::ng-deep > .so-scroll-area {
    flex: 1 1 auto;
    min-height: 0;
  }
}

.data-table {
  width: 100%;
  min-width: max(100%, 42rem);
  border-spacing: 0;
  border-collapse: collapse;
  color: var(--text-color);
  font-size: var(--text-sm);
  text-align: start;
  background: var(--surface-background);
}

.data-table__caption {
  padding: var(--space-4);
  color: var(--text-color);
  font-size: var(--text-md);
  font-weight: var(--font-weight-title);
  text-align: start;
}

.data-table__caption--hidden,
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

th,
td {
  width: var(--data-table-column-width, auto);
  padding: var(--space-4) var(--space-5);
  border-bottom: 1px solid var(--border-color);
  vertical-align: middle;
}

.data-table__region--compact th,
.data-table__region--compact td {
  padding: var(--space-3);
}

th {
  position: sticky;
  top: 0;
  z-index: 15;
  background-color: var(--table-header-bg);
  color: var(--table-header-color);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-display);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  white-space: nowrap;
  border-bottom: var(--table-header-border-width) var(--table-header-border-style)
    var(--table-header-border-color);
  box-shadow: var(--table-header-shadow);
}

td {
  color: var(--text-color-secondary);
}

td[data-label='Cliente'],
td[data-label='Persona'],
td[data-label='Usuario'] {
  color: var(--text-color);
  font-weight: var(--font-weight-emphasis);
}

tbody tr {
  background-color: var(--surface-background);
  transition: background-color 140ms ease;
}

tbody tr:not(.data-table__state-row):hover {
  background: var(--hover-background);
}

tbody tr:last-child td {
  border-bottom: 0;
}

.data-table__heading {
  display: inline-flex;
  min-height: 2.75rem;
  align-items: center;
}

.data-table__sort-button {
  width: 100%;
  min-height: 2.75rem;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: var(--space-2);
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  letter-spacing: inherit;
  text-align: inherit;
  text-transform: inherit;
}

.data-table__sort-button:hover {
  background: color-mix(in srgb, currentColor 8%, transparent);
}

.data-table__sort-button:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.data-table__sort-indicator {
  color: var(--primary-color);
  font-size: var(--text-md);
  line-height: 1;
}

.data-table__cell--start {
  text-align: start;
}

.data-table__cell--center {
  text-align: center;
}

.data-table__cell--center .data-table__sort-button {
  justify-content: center;
}

.data-table__cell--end {
  text-align: end;
}

.data-table__cell--end .data-table__sort-button {
  justify-content: flex-end;
}

// En tarjetas móviles, centrar el valor sin desplazar su etiqueta ::before.
.data-table__cell--center > app-chip {
  justify-self: center;
}

.data-table__cell--end > app-chip {
  justify-self: end;
}

.data-table__actions,
.data-table__actions-heading {
  text-align: center;
  width: var(--data-table-actions-width, 12rem);
  min-width: var(--data-table-actions-width, 12rem);
  white-space: nowrap;
  position: sticky;
  right: 0;
  transition: box-shadow 0.2s ease, background-color 0.2s ease;
}

.data-table__actions-heading {
  z-index: 20;
  background-color: var(--table-header-bg);
}

.data-table__actions {
  z-index: 10;
  background-color: inherit;
}

.data-table__actions-heading::before,
.data-table__actions::before {
  content: '';
  position: absolute;
  inset: 0;
  background-color: var(--text-color);
  opacity: 0.08;
  pointer-events: none;
  z-index: -1;
}

.data-table:not(.data-table--scrolled-right) .data-table__actions-heading,
.data-table:not(.data-table--scrolled-right) .data-table__actions {
  border-left: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
}

.data-table__cell--end .data-table__sort-button {
  justify-content: flex-end;
}

.data-table__cell--end {
  font-variant-numeric: tabular-nums;
}

.data-table__action-list,
.row-actions {
  display: inline-flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
}

.data-table__state-row:hover {
  background: transparent;
}

.data-table__state-row td {
  padding: var(--space-8) var(--space-4);
}

.data-table__state {
  min-height: 5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: var(--space-3);
  color: var(--text-color-secondary);
  text-align: center;
}

.data-table__state--inline {
  min-height: 0;
  justify-content: space-between;
  text-align: start;
  color: inherit;
}

.data-table__spinner {
  width: 1.25rem;
  height: 1.25rem;
  border: 2px solid var(--border-color-strong);
  border-right-color: var(--primary-color);
  border-radius: var(--radius-full);
  animation: data-table-spin 700ms linear infinite;
}

.data-table__retry {
  flex: 0 0 auto;
}

/* DATA TABLE TOOLBAR & TOP PAGINATION */
.data-table__toolbar {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  row-gap: var(--space-3);
  column-gap: var(--form-row-gap, 2.25rem);
  padding: var(--space-3) var(--space-5);
  border-bottom: 1px solid var(--border-color);
  background: var(--surface-section);
  color: var(--text-color-secondary);
  font-size: var(--text-sm);
}

.data-table__summary strong {
  color: var(--text-color);
  font-weight: var(--font-weight-display);
}

.data-table__pagination {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  row-gap: var(--space-2);
  column-gap: var(--form-row-gap, 2.25rem);
}

.data-table__page-size {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

.data-table__page-size app-form-select,
.data-table__page-size app-select2 {
  width: var(--pagination-page-size-inline-size, 5rem);
  min-width: var(--pagination-page-size-inline-size, 5rem);
  max-width: var(--pagination-page-size-inline-size, 5rem);
  flex: 0 0 var(--pagination-page-size-inline-size, 5rem);
  --control-height: 2.125rem;
  --select2-min-width: var(--pagination-page-size-inline-size, 5rem);
}

.data-table__page-info {
  font-weight: var(--font-weight-emphasis);
}

.data-table__page-buttons {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
}

.data-table__page-btn {
  width: 2.25rem;
  height: 2.25rem;
  display: inline-grid;
  place-items: center;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--surface-background);
  color: var(--text-color);
  cursor: pointer;
  font-size: var(--text-sm);
  transition: all 140ms ease;
}

.data-table__page-btn:not(:disabled):hover {
  background: var(--brand-primary-50);
  border-color: var(--primary-color);
  color: var(--primary-color);
}

.data-table__page-btn:disabled {
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

@keyframes data-table-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 48rem) {
  .data-table__toolbar {
    align-items: stretch;
  }

  .data-table__summary,
  .data-table__pagination {
    width: 100%;
  }

  .data-table__pagination {
    justify-content: space-between;
  }

  .data-table {
    min-width: 0;
    display: block;
    padding: var(--space-3);
  }

  .data-table__caption:not(.data-table__caption--hidden) {
    display: block;
    padding: var(--space-2) 0 var(--space-4);
  }

  thead {
    display: none;
  }

  tbody {
    display: grid;
    gap: var(--space-3);
  }

  tbody tr:not(.data-table__state-row) {
    min-width: 0;
    display: grid;
    overflow: hidden;
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    background: var(--surface-background);
  }

  tbody tr:not(.data-table__state-row):hover {
    background: var(--surface-background);
  }

  tbody tr:not(.data-table__state-row) td {
    width: auto;
    min-width: 0;
    display: grid;
    grid-template-columns: minmax(7.5rem, 40%) minmax(0, 1fr);
    align-items: center;
    gap: var(--space-3);
    padding: var(--space-3);
    overflow-wrap: anywhere;
    text-align: start;
    white-space: normal;
  }

  tbody tr:not(.data-table__state-row) td::before {
    content: attr(data-label);
    color: var(--text-color-secondary);
    font-size: var(--text-2xs);
    font-weight: var(--font-weight-display);
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  tbody tr:not(.data-table__state-row) td:last-child {
    border-bottom: 0;
  }

  
  
  .data-table__actions {
    /* Reset from desktop */
    display: grid !important;
    background-color: transparent;
  }
  
  .data-table__actions::before {
    position: static;
    background-color: transparent;
    opacity: 1;
    z-index: auto;
    pointer-events: auto;
    inset: auto;
  }

  .data-table__action-list {
    justify-content: center;
    width: 100%;
  }



  

  .data-table__state-row,
  .data-table__state-row td {
    display: block;
  }

  .data-table__state-row td {
    padding: var(--space-5) 0;
    border: 0;
  }

  .data-table__state--inline {
    align-items: stretch;
    flex-direction: column;
  }

  .data-table__retry {
    width: 100%;
  }
}

@media (max-width: 36rem) {
  .data-table__pagination {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (prefers-reduced-motion: reduce) {
  tbody tr {
    transition: none;
  }

  .data-table__spinner {
    animation-duration: 1.4s;
  }
}

