:host {
  display: block;
  position: relative;
  width: 100%;
}

/* === TRIGGER AREA === */
.datepicker-trigger {
  position: relative;
  cursor: pointer;
}

.datepicker-trigger:focus,
.datepicker-trigger:focus-visible {
  outline: none;
  box-shadow: none;
}

.datepicker-wrapper {
  position: relative;
  margin-top: var(--space-3);
}

/* variant="standard": la etiqueta superior ocupa el espacio que reserva el modo flotante. */
.datepicker-wrapper--standard {
  margin-top: 0;
}

.datepicker-top-label {
  margin-bottom: var(--field-label-gap);
}

::ng-deep .datepicker-trigger app-floating-input .floating-input-wrapper {
  margin-top: 0;
}

/* Icon overrides for the input trigger */
.calendar-icon-btn {
  position: absolute;
  right: 1rem;
  top: calc(var(--control-height, 3rem) / 2);
  transform: translateY(-50%);
  box-sizing: border-box;
  border: none;
  background: transparent;
  cursor: pointer;
  color: var(--text-color-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--space-7);
  height: var(--space-7);
  border-radius: 50%;
  transition: background-color 0.2s;
  z-index: 20;
  /* Above input label */
}

.calendar-icon-btn:hover {
  background-color: var(--hover-background-subtle);
  color: var(--primary-color);
}

/* === DROPDOWN POPUP === */
.datepicker-popup {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 1000;
  margin-top: var(--space-2);
  background: var(--surface-elevated);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  /*
    El calendario es un popover: flota sobre la pagina y sobre las tarjetas que
    hay debajo. `--shadow-dropdown` pesa alfa 0,1 en tema claro y en los oscuros
    no trae el anillo de 1px con el que la escala separa una superficie del
    fondo, asi que el panel quedaba mas plano que aquello sobre lo que se abre.
  */
  box-shadow: var(--shadow-lg);
  padding: var(--space-4);
  width: 20rem;
  box-sizing: border-box;
  animation: slideDown 0.2s ease-out;
  transform-origin: top left;
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-0.625rem);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* === HEADER (Month/Year Nav) === */
.calendar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-4);
}

.current-month {
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color);
  font-size: var(--text-md);
  text-transform: capitalize;
}

.nav-btn {
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  width: var(--space-6);
  height: var(--space-6);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text-color-secondary);
  transition: all 0.2s;
}

.nav-btn:hover {
  background-color: var(--hover-background);
  color: var(--primary-color);
  border-color: var(--primary-color);
}

/* === CALENDAR GRID === */
.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: var(--space-1);
  text-align: center;
}

.weekday-label {
  /* gate-etiqueta-exento: cabecera de columna de dias del calendario, no es la etiqueta de un campo. */
  font-size: var(--text-xs);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color-muted);
  padding-bottom: var(--space-2);
  text-transform: uppercase;
}

.calendar-day {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-sm);
  cursor: pointer;
  border-radius: 50%;
  transition: all 0.2s;
  color: var(--text-color);
  user-select: none;
}

.calendar-day:hover:not(.empty):not(.disabled) {
  background-color: var(--hover-background);
  color: var(--primary-color);
}

.calendar-day.empty {
  cursor: default;
}

.calendar-day.today {
  font-weight: var(--font-weight-title);
  color: var(--primary-color);
  border: 1px solid var(--primary-color);
}

.calendar-day.selected {
  background-color: var(--primary-color);
  color: var(--text-color-on-primary);
  font-weight: var(--font-weight-emphasis);
}

/* Ver form-input/input.scss: `--text-color-disabled` ya define el contraste
   por tema y la opacidad lo dividia. */
.calendar-day.disabled {
  color: var(--text-color-disabled);
  cursor: not-allowed;
}

/*
 * Dark mode se maneja automáticamente via tokens semánticos.
 * --surface-elevated, --border-color, etc. ya tienen valores
 * apropiados para temas oscuros.
 */

/* === MONTH / YEAR GRIDS === */
.month-grid,
.year-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-2);
  padding: var(--space-2);
}

.calendar-option {
  padding: var(--space-2);
  border-radius: var(--radius-md);
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: var(--font-weight-body);
  color: var(--text-color);
  transition: all 0.2s;
  text-transform: capitalize;
}

.calendar-option:hover {
  background-color: var(--hover-background);
  color: var(--primary-color);
}

.calendar-option.selected {
  background-color: var(--primary-color);
  color: var(--text-color-on-primary);
  font-weight: var(--font-weight-emphasis);
}

.calendar-option.current {
  color: var(--primary-color);
  background-color: var(--hover-background);
  font-weight: var(--font-weight-title);
  border: 1px solid var(--primary-color);
}

::ng-deep .datepicker-trigger app-floating-input input.floating-input {
  padding-right: 3rem;
  box-sizing: border-box;
}

/*
  Estilos compartidos de la etiqueta de campo (contrato `variant`: standard | floating | floating-value).

  Se incluyen en cada control con `styleUrls: ['./x.css', '../form-field/field-label.css']`, de modo
  que la tipografia, el color y la geometria de la etiqueta salen de UN solo lugar y de tokens
  `--field-label-*`: nada de rem literales ni `uppercase` en los controles.

  Geometria de la etiqueta flotante
  ---------------------------------
  `.fl-control` es la CAJA del control y solo contiene el control. La ayuda y el error viven FUERA
  de ella. Si la etiqueta se anclara al contenedor que tambien lleva la ayuda, `top: 50%` caeria
  en el centro de caja + ayuda y la etiqueta quedaria desplazada hacia abajo cuando hay mensaje.

  - Reposo:  centrada en la mitad de `--control-height` (primera linea en controles multilinea).
  - Elevada: centrada sobre el borde superior (`top: 0` + `translateY(-50%)`), con el fondo del
             campo recortando el borde. Como el centrado es relativo al propio texto, no depende
             del tamano de fuente.
*/

.fl-field {
  display: grid;
  min-width: 0;
  gap: var(--field-label-gap);
}

/* Reserva el espacio que ocupa la etiqueta elevada sobre el borde superior del control. */
.fl-field--floating {
  margin-top: var(--space-3);
}

/* El mensaje de error lo dibuja app-form-error: la rejilla ya separa, asi que no suma su propio margen. */
.fl-field > app-form-error {
  --form-error-gap: 0;
}

.fl-control {
  position: relative;
  min-width: 0;
}

/* Etiqueta superior (variant="standard"). */
.fl-label {
  display: block;
  color: var(--field-label-color);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
}

.field__required,
.fl-label__required {
  color: var(--field-label-color-error);
}

/* Etiqueta flotante (variant="floating" | "floating-value"): reposo. */
.fl-label--floating {
  position: absolute;
  top: calc(var(--control-height) / 2);
  left: var(--field-label-inset);
  z-index: 1;
  max-width: calc(100% - var(--field-label-inset) - var(--space-1));
  overflow: hidden;
  padding: var(--field-label-padding);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--field-label-color-resting);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
  transform: translateY(-50%);
  transition:
    top var(--field-label-duration) ease,
    color var(--field-label-duration) ease,
    font-size var(--field-label-duration) ease;
}

/* Etiqueta flotante: elevada sobre el borde superior. */
.fl-label--floating.fl-label--floated {
  top: 0;
  background: var(--input-bg);
  color: var(--field-label-color-floated);
  font-size: var(--field-label-floated-font-size);
  font-weight: var(--field-label-floated-font-weight);
}

.fl-label.fl-label--disabled,
.fl-label--floating.fl-label--disabled {
  color: var(--input-disabled-text);
}

.fl-label--floating.fl-label--floated.fl-label--disabled {
  background: var(--input-disabled-bg);
}

.fl-label.fl-label--error,
.fl-label--floating.fl-label--error,
.fl-label--floating.fl-label--floated.fl-label--error {
  color: var(--field-label-color-error);
}

@media (prefers-reduced-motion: reduce) {
  .fl-label--floating {
    transition: none;
  }
}

