      background-color: var(--bg-secondary);
      color: var(--text-primary);
      padding: 20px;
      border-radius: 8px;
      transition: all 300ms ease;
    }

    .theme-indicator {
      margin-top: 15px;
      font-size: 1.1rem;
      font-weight: var(--font-weight-emphasis);
    }
  `]
