:host {
  display: block;
  width: 100%;
}

:host:has(> .floating-input-wrapper.has-custom-width) {
  width: fit-content;
  max-width: 100%;
}

.floating-input-wrapper {
  position: relative;
  width: var(--floating-input-width, 100%);
  min-width: var(--fi-min-width, var(--floating-input-width, 8rem)); /* Controlable desde el contenedor padre. */
  margin-top: var(--space-3);
}

/* === BASE INPUT === */
.floating-input {
  width: 100%;
  height: var(--control-height);
  padding: 0 var(--space-4);
  line-height: calc(var(--control-height) - var(--space-1)); /* Robust vertical centering */
  font-size: 0.875rem;
  color: var(--input-text);
  background: transparent;
  border: none;
  outline: none;
  transition: border-color 200ms ease, box-shadow 200ms ease;
  box-sizing: border-box; /* Ensure padding doesn't affect height */
}

.floating-input:focus,
.floating-input:focus-visible {
  outline: none;
  box-shadow: none;
}

/* Standardize date and number inputs */
.floating-input[type="date"],
.floating-input[type="number"] {
  line-height: normal; /* Reset line-height to prevent expansion */
  height: var(--control-height);
  box-sizing: border-box;
  margin: 0;
}

/* Reset native date picker indicator spacing */
.floating-input::-webkit-calendar-picker-indicator {
  margin: 0;
  padding: 0;
}

/* Reveal mask only when focused or has value to prevent label overlap */
.floating-input-wrapper:not(.variant-standard):not(.focused):not(.has-value) .floating-input::-webkit-datetime-edit {
  color: transparent;
}

.has-icon .floating-input {
  padding-right: var(--space-8);
}

.floating-input::placeholder {
  color: var(--input-placeholder);
}

/* WebView2: el revelado pertenece al control Atomic y no al navegador. */
.floating-input::-ms-reveal,
.floating-input::-ms-clear {
  display: none;
}

.floating-input::-webkit-search-cancel-button {
  -webkit-appearance: none;
  appearance: none;
  display: none;
}

/* === FLOATING LABEL === */
.floating-label {
  position: absolute;
  left: var(--field-label-inset);
  top: calc(var(--control-height) / 2);
  transform: translateY(-50%);
  max-width: calc(100% - var(--field-label-inset) - var(--space-1));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
  color: var(--field-label-color-resting);
  pointer-events: none;
  transition:
    top 200ms cubic-bezier(0.4, 0, 0.2, 1),
    transform 200ms cubic-bezier(0.4, 0, 0.2, 1),
    color 200ms cubic-bezier(0.4, 0, 0.2, 1),
    font-size 200ms cubic-bezier(0.4, 0, 0.2, 1);
  transform-origin: left center;
  z-index: 10; /* Ensure label sits above borders/content */
}

.has-icon:not(.focused):not(.has-value) .floating-label,
.has-icon.label-solo-valor:not(.has-value) .floating-label {
  max-width: calc(100% - var(--space-7) - var(--field-label-inset));
}

/* Label goes up when focused or has value */
.focused .floating-label,
.has-value .floating-label {
  top: var(--space-1);
  transform: translateY(0);
  font-size: var(--field-label-floated-font-size);
  font-weight: var(--field-label-floated-font-weight);
  color: var(--field-label-color-floated);
}

/* === INPUT LINE (for underline/material) === */
.input-line {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: var(--space-1);
  background: var(--input-border);
}

.input-line::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 0;
  height: var(--space-1);
  background: var(--info-color);
  transition: all 300ms cubic-bezier(0.4, 0, 0.2, 1);
  transform: translateX(-50%);
}

.focused .input-line::after {
  width: 100%;
}

/* === VARIANT: FLOATING === */
.variant-floating .floating-input {
  height: var(--control-height);
  /* padding inherited from base: 0 0.875rem */
  border: var(--input-border-width, 1.5px) solid var(--input-border);
  border-radius: var(--radius-md);
  background: var(--input-bg);
  font-size: 0.875rem;
  box-shadow: var(--input-shadow);
}

.variant-floating .floating-label {
  left: var(--field-label-inset);
  background: var(--input-bg);
  padding: var(--field-label-padding);
  border-radius: var(--radius-sm);
  white-space: nowrap;
}

.variant-floating.focused .floating-label,
.variant-floating.has-value .floating-label {
  top: 0;
  transform: translateY(-50%);
}

.variant-floating.focused .floating-input {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.variant-floating .input-line {
  display: none;
}

/* === VARIANT: UNDERLINE === */
.variant-underline .floating-input {
  height: var(--control-height);
  padding: var(--space-5) var(--space-4) 0;
  line-height: 1.5; /* Reset line-height for underline */
  font-size: 0.875rem;
  border-bottom: 1px solid var(--input-border);
}

.variant-underline.has-icon .floating-input {
  padding-right: var(--space-8);
}

.variant-underline .floating-label {
  left: var(--field-label-inset);
  padding: var(--field-label-padding);
}

.variant-underline.focused .floating-label,
.variant-underline.has-value .floating-label {
  top: var(--space-1);
}

.variant-underline.focused .floating-input,
.variant-underline.has-value .floating-input {
  border-bottom-color: transparent;
}

.variant-underline .input-line {
  height: var(--space-1);
}

/* === VARIANT: MATERIAL === */
.variant-material .floating-input {
  height: var(--control-height);
  padding: var(--space-5) var(--space-4) 0;
  line-height: 1.5;
  font-size: 0.875rem;
}

.variant-material.has-icon .floating-input {
  padding-right: var(--space-8);
}

.variant-material .floating-label {
  left: var(--field-label-inset);
  padding: var(--field-label-padding);
  font-size: var(--field-label-font-size);
}

.variant-material.focused .floating-label,
.variant-material.has-value .floating-label {
  top: var(--space-1);
}

/* === VARIANT: OUTLINE === */
.variant-outline .floating-input {
  height: var(--control-height);
  /* padding inherited from base: 0 0.875rem */
  font-size: 0.875rem;
  background: var(--input-bg);
  border: var(--input-border-width, 1.5px) solid var(--input-border);
  border-radius: var(--radius-md);
  box-shadow: var(--input-shadow);
}

.variant-outline .floating-label {
  top: calc(var(--control-height) / 2);
  background: var(--input-bg);
  padding: var(--field-label-padding);
  border-radius: var(--radius-sm);
  font-size: var(--field-label-font-size);
  white-space: nowrap;
}

.variant-outline.focused .floating-label,
.variant-outline.has-value .floating-label {
  top: 0;
  font-size: var(--field-label-floated-font-size);
  transform: translateY(-50%);
}

.variant-outline.focused .floating-input {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.variant-outline .input-line {
  display: none;
}

/* === HOVER STATE (floating + outline, antes del focus) === */
.variant-floating:not(.focused) .floating-input:hover,
.variant-outline:not(.focused) .floating-input:hover {
  border-color: var(--input-border-hover);
  box-shadow: var(--input-shadow-hover);
}

/* === ICONS === */
.input-icon {
  position: absolute;
  right: 0.875rem;
  top: calc(var(--control-height) / 2);
  transform: translateY(-50%);
  color: var(--text-color-muted);
  font-size: var(--space-4);
  /* Fix strict sizing to prevent height variations */
  width: var(--space-5);
  height: var(--space-5);
  display: flex;
  align-items: center;
  justify-content: center;
}

.input-icon-btn {
  position: absolute;
  right: var(--space-2);
  top: calc(var(--control-height) / 2);
  transform: translateY(-50%);
  width: var(--space-7);
  height: var(--space-7);
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: 50%;
  color: var(--text-color-secondary);
  cursor: pointer;
  transition: all 150ms ease;
}

.input-icon-btn:hover {
  background: var(--hover-background-subtle);
  color: var(--primary-color);
}

.input-icon-btn:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus-primary);
}

.input-icon-btn:disabled {
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

.input-icon-btn:disabled:hover {
  background: transparent;
  color: var(--text-color-secondary);
}

.input-icon-btn--static {
  width: 1.75rem;
  height: 1.75rem;
  right: var(--space-3);
  cursor: default;
}

.input-icon-btn--static.floating-input__icon--clickable {
  cursor: pointer;
}

.input-icon-btn i {
  font-size: var(--space-4);
}

/* === STATES === */
.disabled .floating-input {
  background: var(--input-disabled-bg);
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

.disabled .floating-label,
.disabled.focused .floating-label,
.disabled.has-value .floating-label {
  color: var(--input-disabled-text);
}

.disabled.variant-floating .floating-label,
.disabled.variant-outline .floating-label {
  background: var(--input-disabled-bg);
}

.has-error .floating-input {
  border-color: var(--danger-color) !important;
}

.has-error .floating-label {
  color: var(--danger-color-text) !important;
}

.has-error .input-line::after {
  background: var(--danger-color);
}

.input-error {
  display: block;
  margin-top: var(--space-2);
  font-size: 0.8125rem;
  color: var(--danger-color-text);
}

/* Dark mode handled automatically by CSS variables */

/* === VARIANT: STANDARD (etiqueta superior fija) ===
   La etiqueta la dibuja la plantilla sobre el campo (.fl-label); aqui solo se pinta la caja. */
.floating-input-top-label {
  margin-bottom: var(--field-label-gap);
}

.variant-standard {
  margin-top: 0;
}

.variant-standard .floating-input {
  height: var(--control-height);
  border: var(--input-border-width, 1.5px) solid var(--input-border);
  border-radius: var(--radius-md);
  background: var(--input-bg);
  box-shadow: var(--input-shadow);
}

.variant-standard.focused .floating-input {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.variant-standard .input-line {
  display: none;
}

.variant-standard:not(.focused) .floating-input:hover {
  border-color: var(--input-border-hover);
  box-shadow: var(--input-shadow-hover);
}

/* === MOMENTO DE LA ETIQUETA: floating-value ===
   Misma caja que `floating`, pero enfocar un campo vacio no sube la etiqueta: solo el valor. */
.label-solo-valor.focused:not(.has-value) .floating-label {
  top: calc(var(--control-height) / 2);
  transform: translateY(-50%);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  color: var(--field-label-color-resting);
}

/*
  Estilos compartidos de la etiqueta de campo (contrato `variant`: standard | floating | floating-value).

  Se incluyen en cada control con `styleUrls: ['./x.css', '../form-field/field-label.css']`, de modo
  que la tipografia, el color y la geometria de la etiqueta salen de UN solo lugar y de tokens
  `--field-label-*`: nada de rem literales ni `uppercase` en los controles.

  Geometria de la etiqueta flotante
  ---------------------------------
  `.fl-control` es la CAJA del control y solo contiene el control. La ayuda y el error viven FUERA
  de ella. Si la etiqueta se anclara al contenedor que tambien lleva la ayuda, `top: 50%` caeria
  en el centro de caja + ayuda y la etiqueta quedaria desplazada hacia abajo cuando hay mensaje.

  - Reposo:  centrada en la mitad de `--control-height` (primera linea en controles multilinea).
  - Elevada: centrada sobre el borde superior (`top: 0` + `translateY(-50%)`), con el fondo del
             campo recortando el borde. Como el centrado es relativo al propio texto, no depende
             del tamano de fuente.
*/

.fl-field {
  display: grid;
  min-width: 0;
  gap: var(--field-label-gap);
}

/* Reserva el espacio que ocupa la etiqueta elevada sobre el borde superior del control. */
.fl-field--floating {
  margin-top: var(--space-3);
}

/* El mensaje de error lo dibuja app-form-error: la rejilla ya separa, asi que no suma su propio margen. */
.fl-field > app-form-error {
  --form-error-gap: 0;
}

.fl-control {
  position: relative;
  min-width: 0;
}

/* Etiqueta superior (variant="standard"). */
.fl-label {
  display: block;
  color: var(--field-label-color);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
}

.field__required,
.fl-label__required {
  color: var(--field-label-color-error);
}

/* Etiqueta flotante (variant="floating" | "floating-value"): reposo. */
.fl-label--floating {
  position: absolute;
  top: calc(var(--control-height) / 2);
  left: var(--field-label-inset);
  z-index: 1;
  max-width: calc(100% - var(--field-label-inset) - var(--space-1));
  overflow: hidden;
  padding: var(--field-label-padding);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--field-label-color-resting);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
  transform: translateY(-50%);
  transition:
    top var(--field-label-duration) ease,
    color var(--field-label-duration) ease,
    font-size var(--field-label-duration) ease;
}

/* Etiqueta flotante: elevada sobre el borde superior. */
.fl-label--floating.fl-label--floated {
  top: 0;
  background: var(--input-bg);
  color: var(--field-label-color-floated);
  font-size: var(--field-label-floated-font-size);
  font-weight: var(--field-label-floated-font-weight);
}

.fl-label.fl-label--disabled,
.fl-label--floating.fl-label--disabled {
  color: var(--input-disabled-text);
}

.fl-label--floating.fl-label--floated.fl-label--disabled {
  background: var(--input-disabled-bg);
}

.fl-label.fl-label--error,
.fl-label--floating.fl-label--error,
.fl-label--floating.fl-label--floated.fl-label--error {
  color: var(--field-label-color-error);
}

@media (prefers-reduced-motion: reduce) {
  .fl-label--floating {
    transition: none;
  }
}

