  margin-top: var(--form-error-gap, var(--space-1));
  font-size: var(--text-xs);
  /* --danger-color es el token de RELLENO y no pinta texto: sobre la superficie
     clara del formulario se queda en 3,24:1. --danger-color-text es el que trae el
     contraste calculado. El respaldo #ef4444 tampoco era respaldo de nada, porque
     el token esta definido en los tres temas. */
  color: var(--danger-color-text);
  animation: error-in 150ms ease;
}

@keyframes error-in {
  from { opacity: 0; transform: translateY(calc(-1 * var(--space-1))); }
  to { opacity: 1; transform: translateY(0); }
}

.error-icon {
  font-size: var(--space-3);
  margin-top: var(--space-1);
  flex-shrink: 0;
}

.error-message {
  line-height: 1.4;
}

