import { Component, input, output, HostBinding } from '@angular/core';
import { normalizeFontAwesomeIconClass } from '../button/button.component';

export type IconButtonVariant =
  | 'default'
  | 'ghost'
  | 'avatar'
  | 'close'
  | 'close-ghost'
  | 'close-soft'
  | 'hanging-close';
export type IconButtonAnimation = 'rotate' | 'grow' | 'none' | 'custom';
export type IconButtonSize = 'sm' | 'md' | 'lg';

@Component({
  selector: 'app-icon-button',
  standalone: true,
  imports: [],
  templateUrl: './icon-button.component.html',
  styleUrl: './icon-button.component.css'
})
export class IconButtonComponent {
  /** Button variant */
  readonly variant = input<IconButtonVariant>('default');

  /** Button size */
  readonly size = input<IconButtonSize>('md');

  /** FontAwesome icon class (when not using projected content) */
  readonly icon = input('');

  @HostBinding('class.is-hanging-close')
  get isHangingClose(): boolean {
    return this.variant() === 'hanging-close';
  }

  get isCloseVariant(): boolean {
    const currentVariant = this.variant();
    return (
      currentVariant === 'close' ||
      currentVariant === 'close-ghost' ||
      currentVariant === 'close-soft' ||
      currentVariant === 'hanging-close'
    );
  }

  /** Hover animation for the icon: defaults to 'none' (no animation) */
  readonly animation = input<IconButtonAnimation>('none');

  /** Tooltip text */
  readonly tooltip = input('');

  /** Native title alias */
  readonly title = input('');

  /** Accessibility label */
  readonly ariaLabel = input('');

  /** Badge count (for notifications) */
  readonly badge = input(0);

  /** Disabled state */
  readonly disabled = input(false);

  /** Click event */
  readonly clicked = output<MouseEvent>();

  get resolvedTitle(): string {
    return this.tooltip() || this.title() || this.ariaLabel() || (this.isCloseVariant ? 'Cerrar' : '');
  }

  get resolvedAriaLabel(): string {
    return this.ariaLabel() || this.tooltip() || this.title() || (this.isCloseVariant ? 'Cerrar' : '');
  }

  get resolvedIcon(): string {
    return normalizeFontAwesomeIconClass(this.icon());
  }
}

styleUrlsData.data:
:host {
  display: inline-block;
}

.icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--control-height);
  height: var(--control-height);
  padding: 0;
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  color: var(--text-color-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
}

.icon-btn--sm {
  width: var(--control-height-sm);
  height: var(--control-height-sm);
  border-radius: var(--radius-sm);
}

.icon-btn--lg {
  width: var(--control-height-lg);
  height: var(--control-height-lg);
  border-radius: var(--radius-lg);
}

.icon-btn:hover:not(:disabled) { background: var(--surface-hover); color: var(--primary-color); transform: translateY(-0.125rem) scale(1.05); box-shadow: var(--shadow-md); filter: brightness(1.1); }

.icon-btn:active {
  transform: scale(0.95);
}

.icon-btn:disabled {
  cursor: not-allowed;
  background: transparent;
  color: var(--text-color-secondary);
  transform: none !important;
}

.icon-btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.icon-btn--close:focus-visible,
.icon-btn--close-ghost:focus-visible,
.icon-btn--close-soft:focus-visible,
.icon-btn--hanging-close:focus-visible {
  outline: 2px solid var(--danger-color);
  outline-offset: 2px;
}

/* Ghost variant - más sutil */
.icon-btn--ghost {
  border: 1px solid transparent;
  box-shadow: none;
}

.icon-btn--ghost:hover:not(:disabled) {
  background: transparent;
  color: var(--primary-color);
  box-shadow: none;
  border: 1px solid transparent;
}

/* Avatar variant - circular con gradiente */
.icon-btn--avatar {
  background: linear-gradient(
    135deg,
    var(--button-primary-bg, var(--primary-color)),
    var(--brand-primary-700, var(--primary-color-dark))
  );
  border-radius: 50%;
  border: none;
  box-shadow: none;
  color: var(--text-color-on-primary);
}

.icon-btn--avatar:hover:not(:disabled) {
  background: linear-gradient(
    135deg,
    var(--brand-primary-700, var(--primary-color-dark)),
    var(--button-primary-bg, var(--primary-color))
  );
  color: var(--text-color-on-primary);
  transform: scale(1.05);
  box-shadow: var(--shadow-glow-primary);
  filter: none;
}

.icon-btn--avatar:not(:disabled) ::ng-deep i,
.icon-btn--avatar:not(:disabled) ::ng-deep svg,
.icon-btn--avatar:hover:not(:disabled) ::ng-deep i,
.icon-btn--avatar:hover:not(:disabled) ::ng-deep svg {
  color: var(--text-color-on-primary);
}

/* Badge */
.icon-btn__badge {
  position: absolute;
  top: -0.25rem;
  right: -0.25rem;
  min-width: 1.125rem;
  height: 1.125rem;
  padding: 0 var(--space-1);
  font-size: 0.625rem;
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color-on-primary);
  background: var(--danger-color);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
}

/* SVG icons inside */
:host ::ng-deep svg {
  width: 1.25rem;
  height: 1.25rem;
}

/* Standardized Icon Animations */
:host ::ng-deep i.icon,
:host ::ng-deep i.configuration-icon,
:host ::ng-deep i.fa-solid,
:host ::ng-deep i.fa-regular,
:host ::ng-deep i.fa-brands {
  transition: color 200ms ease, transform 200ms ease;
}


/* Rotate Animation (Default) */
.icon-anim-rotate:hover:not(:disabled) ::ng-deep i.icon,
.icon-anim-rotate:hover:not(:disabled) ::ng-deep i.configuration-icon,
.icon-anim-rotate:hover:not(:disabled) ::ng-deep i.fa-solid,
.icon-anim-rotate:hover:not(:disabled) ::ng-deep i.fa-regular,
.icon-anim-rotate:hover:not(:disabled) ::ng-deep i.fa-brands {
  transform: scale(1.1) rotate(180deg);
  color: currentColor;
}

/* Grow Animation */
.icon-anim-grow:hover:not(:disabled) ::ng-deep i.icon,
.icon-anim-grow:hover:not(:disabled) ::ng-deep i.configuration-icon,
.icon-anim-grow:hover:not(:disabled) ::ng-deep i.fa-solid,
.icon-anim-grow:hover:not(:disabled) ::ng-deep i.fa-regular,
.icon-anim-grow:hover:not(:disabled) ::ng-deep i.fa-brands {
  transform: scale(1.15);
  color: currentColor;
}

/* None Animation */
.icon-anim-none:hover:not(:disabled) ::ng-deep i.icon,
.icon-anim-none:hover:not(:disabled) ::ng-deep i.configuration-icon,
.icon-anim-none:hover:not(:disabled) ::ng-deep i.fa-solid,
.icon-anim-none:hover:not(:disabled) ::ng-deep i.fa-regular,
.icon-anim-none:hover:not(:disabled) ::ng-deep i.fa-brands {
  transform: none !important;
  color: currentColor;
}


/* Close variant - efecto fisico de cierre */
.icon-btn--close {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-color-secondary);
  border-radius: var(--radius-full, 50%);
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: none;
}

.icon-btn--close:hover:not(:disabled) {
  background-color: var(--danger-color);
  border-color: var(--danger-color);
  color: var(--text-color-on-primary);
  transform: scale(1.1);
  box-shadow: var(--shadow-md);
}

.icon-btn--close:active:not(:disabled) {
  background-color: var(--danger-color-dark);
  border-color: var(--danger-color-dark);
  transform: scale(0.9);
  box-shadow: var(--shadow-xs);
}

/* Close-ghost variant - neutro en reposo; en hover solo colorea la X en rojo sin pintar fondo ni borde */
.icon-btn--close-ghost {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-color-secondary);
  border-radius: var(--radius-full, 50%);
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: none;
}

.icon-btn--close-ghost:hover:not(:disabled) {
  background: transparent;
  background-color: transparent;
  border-color: transparent;
  color: var(--danger-color-text);
  transform: scale(1.1);
  box-shadow: none;
  filter: none;
}

.icon-btn--close-ghost:active:not(:disabled) {
  background: transparent;
  background-color: transparent;
  border-color: transparent;
  color: var(--danger-color-dark);
  transform: scale(0.92);
  box-shadow: none;
  filter: none;
}

/* Close-soft variant - círculo suave peligro en reposo y sólido en hover */
.icon-btn--close-soft {
  background-color: var(--danger-color-lighter);
  border: 1px solid var(--danger-color-light);
  color: var(--danger-color-text);
  border-radius: var(--radius-full, 50%);
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: none;
}

.icon-btn--close-soft:hover:not(:disabled) {
  background-color: var(--danger-color);
  border-color: var(--danger-color);
  color: var(--text-color-on-primary);
  transform: scale(1.1);
  box-shadow: var(--shadow-md);
}

.icon-btn--close-soft:active:not(:disabled) {
  background-color: var(--danger-color-dark);
  border-color: var(--danger-color-dark);
  transform: scale(0.92);
  box-shadow: var(--shadow-xs);
}

/* Hanging Close Variant */
:host(.is-hanging-close) {
  position: absolute;
  top: calc(-1 * var(--space-3));
  right: calc(-1 * var(--space-3));
  z-index: 100;
  width: 2rem;
  height: 2rem;
}

.icon-btn--hanging-close {
  background-color: var(--surface-background);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-md);
  color: var(--text-color);
  width: 100%;
  height: 100%;
  border-radius: var(--radius-full, 50%);
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.icon-btn--hanging-close:hover:not(:disabled) {
  background-color: var(--danger-color) !important;
  border-color: var(--danger-color) !important;
  color: var(--text-color-on-primary) !important;
  transform: scale(1.1);
}

.icon-btn--hanging-close:active:not(:disabled) {
  transform: scale(0.95) !important;
  box-shadow: var(--shadow-xs) !important;
}

/* --- EXACT CSS From CodePen (rNPjmg) --- */
/* Scaled down to match previous SVG 20x20 size natively (1em = 50px proportion) */
.close {
  position: relative;
  display: inline-block;
  font-size: var(--text-xl);
  width: 1em;
  height: 1em;
  overflow: hidden;
}

.icon-btn--sm .close {
  font-size: var(--text-md);
}

.icon-btn--lg .close {
  font-size: 1.375rem;
}
.close::before, .close::after {
  content: "";
  position: absolute;
  height: 0.04em;
  width: 100%;
  top: 50%;
  left: 0;
  margin-top: -0.02em;
  background: currentColor;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}
.close::before {
  -webkit-transform: rotate(45deg);
  -moz-transform: rotate(45deg);
  -ms-transform: rotate(45deg);
  -o-transform: rotate(45deg);
  transform: rotate(45deg);
}
.close::after {
  -webkit-transform: rotate(-45deg);
  -moz-transform: rotate(-45deg);
  -ms-transform: rotate(-45deg);
  -o-transform: rotate(-45deg);
  transform: rotate(-45deg);
}
.close.heavy::before, .close.heavy::after {
  height: 0.24em;
  margin-top: -0.12em;
}
.close.blades::before, .close.blades::after {
  border-radius: 0.1em 0;
}
/* --------------------------------------- */

