  color: var(--kpi-accent);
  opacity: 0.85;
}

.kpi-card__chart svg {
  width: 100%;
  height: 100%;
}

@media (max-width: 40rem) {
  .kpi-card {
    min-height: 5.5rem;
    padding: var(--space-3);
  }
}

