:host {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  vertical-align: middle;
}

.loader-container {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: var(--loader-size);
  min-height: var(--loader-size);
  --loader-size: var(--space-7);
  --loader-thickness: var(--border-width-thick);
  --loader-stroke: 4;
  --loader-gradient-stroke: 4.5;
  /* Map local variables to global tokens */
  --gradient-1: var(--loader-gradient-1);
  --gradient-2: var(--loader-gradient-2);
  --gradient-3: var(--loader-gradient-3);
  --gradient-4: var(--loader-gradient-4);
  --gradient-5: var(--loader-gradient-5);
}

/* Colores del gradiente SVG */
.gradient-1 { stop-color: var(--gradient-1); }
.gradient-2 { stop-color: var(--gradient-2); }
.gradient-3 { stop-color: var(--gradient-3); }
.gradient-4 { stop-color: var(--gradient-4); }
.gradient-5 { stop-color: var(--gradient-5); }

/* ========== TAMAÑOS ========== */
.loader-container.loader-sm {
  --loader-size: var(--space-5);
  --loader-thickness: var(--border-width-medium);
  --loader-stroke: 3.25;
  --loader-gradient-stroke: 3.75;
}

.loader-container.loader-md {
  --loader-size: var(--space-7);
  --loader-thickness: var(--border-width-thick);
  --loader-stroke: 4;
  --loader-gradient-stroke: 4.5;
}

.loader-container.loader-lg {
  --loader-size: var(--space-9);
  --loader-thickness: var(--space-1);
  --loader-stroke: 4.75;
  --loader-gradient-stroke: 5.25;
}

/* ========== 1. SPINNER CON DEGRADADO ========== */
.gradient-spinner {
  width: var(--loader-size);
  height: var(--loader-size);
  animation: spin 1s linear infinite;
}

.gradient-spinner svg {
  width: 100%;
  height: 100%;
}

.spinner-track {
  fill: none;
  stroke: var(--loader-border, var(--border-color));
  stroke-width: var(--loader-stroke);
  opacity: 0.25;
}

.spinner-arc {
  stroke-width: var(--loader-stroke);
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ========== 2. DOTS CON DEGRADADO ========== */
.dots {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: var(--loader-size);
  height: var(--loader-size);
  gap: calc(var(--loader-size) * 0.12);
}

.dot {
  width: calc(var(--loader-size) * 0.2);
  height: calc(var(--loader-size) * 0.2);
  flex-shrink: 0;
  border-radius: 50%;
  animation: dotPulse 1.5s ease-in-out infinite;
  backdrop-filter: blur(var(--space-1)); /* Efecto cristal */
}

.dot-1 { background: var(--gradient-1); animation-delay: 0s; }
.dot-2 { background: var(--gradient-2); animation-delay: 0.15s; }
.dot-3 { background: var(--gradient-3); animation-delay: 0.3s; }
.dot-4 { background: var(--gradient-4); animation-delay: 0.45s; }
.dot-5 { background: var(--gradient-5); animation-delay: 0.6s; }

@keyframes dotPulse {
  0%, 70%, 100% {
    transform: scale(0.5);
    opacity: 0.3;
  }
  35% {
    transform: scale(1);
    opacity: 0.9;
  }
}

/* ========== 3. PULSE CON DEGRADADO ========== */
.pulse {
  position: relative;
  width: var(--loader-size);
  height: var(--loader-size);
}

.pulse-ring {
  position: absolute;
  inset: 0;
  border: var(--loader-thickness) solid transparent;
  border-radius: 50%;
  animation: pulseRing 2s ease-out infinite;
}

.pulse-ring-1 { border-color: var(--gradient-1); animation-delay: 0s; }
.pulse-ring-2 { border-color: var(--gradient-3); animation-delay: 0.4s; }
.pulse-ring-3 { border-color: var(--gradient-5); animation-delay: 0.8s; }

.pulse-core {
  position: absolute;
  inset: 25%;
  background: radial-gradient(circle, var(--gradient-3), var(--gradient-1));
  border-radius: 50%;
  opacity: 0.8;
  animation: pulseCore 2s ease-in-out infinite;
}

@keyframes pulseRing {
  0% {
    transform: scale(0.4);
    opacity: 0.8;
  }
  100% {
    transform: scale(1.4);
    opacity: 0;
  }
}

@keyframes pulseCore {
  0%, 100% { transform: scale(0.7); opacity: 0.6; }
  50% { transform: scale(1); opacity: 0.9; }
}

/* ========== 4. BARRAS CON DEGRADADO ========== */
.bars {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: var(--loader-size);
  gap: calc(var(--loader-size) * 0.08);
  height: var(--loader-size);
}

.bar {
  width: calc(var(--loader-size) * 0.14);
  height: 55%;
  border-radius: var(--radius-sm);
  animation: barBounce 1.2s ease-in-out infinite;
  opacity: 0.8;
}

.bar-1 { background: var(--gradient-1); animation-delay: 0s; }
.bar-2 { background: var(--gradient-2); animation-delay: 0.1s; }
.bar-3 { background: var(--gradient-3); animation-delay: 0.2s; }
.bar-4 { background: var(--gradient-4); animation-delay: 0.3s; }
.bar-5 { background: var(--gradient-5); animation-delay: 0.4s; }

@keyframes barBounce {
  0%, 50%, 100% {
    transform: scaleY(0.4);
    opacity: 0.5;
  }
  25% {
    transform: scaleY(1);
    opacity: 0.9;
  }
}

/* ========== 5. GRADIENT RING ========== */
.gradient-ring {
  width: var(--loader-size);
  height: var(--loader-size);
  animation: spin 1.2s linear infinite;
}

.gradient-ring svg {
  width: 100%;
  height: 100%;
}

.gradient-arc {
  stroke-width: var(--loader-gradient-stroke);
}

/* ========== 6. ORBIT (NUEVO) ========== */
.orbit {
  position: relative;
  width: var(--loader-size);
  height: var(--loader-size);
  animation: spin 2s linear infinite;
}

.orbit-ring {
  position: absolute;
  inset: 8%;
  border: var(--loader-thickness) solid var(--gradient-3);
  border-radius: 50%;
  opacity: 0.3;
}

.orbit-planet {
  position: absolute;
  top: 8%;
  left: 50%;
  width: calc(var(--loader-size) * 0.24);
  height: calc(var(--loader-size) * 0.24);
  background: var(--gradient-5);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0.625rem var(--gradient-5);
}

