:host {
  display: block;

  /* CHROME INVERTIDO: tokens locales, y sin pareja de tema a proposito.
     Los variantes «dark» y «primary» prometen una barra oscura o de marca en
     CUALQUIER tema, asi que su texto no puede salir de los tokens de superficie
     -que se invierten con el tema y dejarian letra oscura sobre chrome oscuro-.
     El lavado de hover tampoco: «--hover-background-subtle» es gris casi blanco
     en tema claro, y con el la barra primaria pintaba texto blanco sobre blanco
     al pasar el raton. Un lavado de blanco funciona sobre cualquiera de las dos
     bases y no depende del tema. */
  --navbar-dark-surface: var(--gray-800);
  --navbar-primary-surface: var(--brand-primary-500);
  --navbar-inverse-text: var(--text-color-on-primary);
  --navbar-inverse-hover: color-mix(in srgb, var(--gray-0) 14%, transparent);
  --navbar-inverse-active: color-mix(in srgb, var(--gray-0) 22%, transparent);
}

/* ======= NAVBAR ======= */
.navbar {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  height: 3.75rem;
  padding: 0 var(--space-6);
  background: var(--surface-background);
  border-bottom: 1px solid var(--border-color);
  /* La barra flota sobre el contenido que hace scroll bajo ella: la sombra dice
     cual de las dos superficies esta arriba, cosa que un borde de 1px no dice. */
  position: relative;
  z-index: 100;
}

/* La sombra es de la barra que FLOTA, no de la que esta en reposo: la base
   es position: relative y no hay nada por debajo que separar. */
.navbar--sticky {
  position: sticky;
  top: 0;
  box-shadow: var(--shadow-md);
}

.navbar--dark {
  background: var(--navbar-dark-surface);
  border-color: transparent;
}
.navbar--dark .navbar__brand-name,
.navbar--dark .navbar__link { color: var(--navbar-inverse-text); }
.navbar--dark .navbar__link:hover { background: var(--navbar-inverse-hover); color: var(--navbar-inverse-text); }
.navbar--dark .navbar__link--active { background: var(--navbar-inverse-active); color: var(--navbar-inverse-text); }
.navbar--dark .navbar__mobile-toggle { color: var(--navbar-inverse-text); }

/* El fondo era «--primary-color», que en tema oscuro resuelve al malva claro
   (#bb6bbb): letra blanca sobre el da 3,54:1, por debajo del 4,5:1 que pide un
   texto pequeno. Anclado al 500 de marca -que no cambia con el tema, igual que
   el gris del variante oscuro- son 10,7:1 en los tres temas, y la barra de
   marca deja de aclararse justo cuando la pagina se oscurece. */
.navbar--primary {
  background: var(--navbar-primary-surface);
  border-color: transparent;
}
.navbar--primary .navbar__brand-name,
.navbar--primary .navbar__link { color: var(--navbar-inverse-text); }
.navbar--primary .navbar__link:hover { background: var(--navbar-inverse-hover); color: var(--navbar-inverse-text); }
/* El activo llevaba «--button-primary-bg-hover», que en tema oscuro resuelve al
   malva claro y devolvia el mismo 3,54:1 con letra blanca que se acaba de
   quitar del fondo. Hover y activo comparten ahora una sola escala -14% y 22%
   de blanco-, que es lo que hace legible «este pesa mas que aquel». */
.navbar--primary .navbar__link--active { background: var(--navbar-inverse-active); color: var(--navbar-inverse-text); }
.navbar--primary .navbar__mobile-toggle { color: var(--navbar-inverse-text); }

.navbar--transparent {
  background: transparent;
  border-color: transparent;
  /* Sin superficie que elevar, la sombra seria un borron flotando en el aire. */
  box-shadow: none;
}

/* Brand */
.navbar__brand {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  text-decoration: none;
  flex-shrink: 0;
}
.navbar__logo { height: 1.75rem; width: auto; }
.navbar__brand-name {
  font-size: var(--text-md);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color);
  white-space: nowrap;
}

/* Nav list */
.navbar__nav {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1;
}

.navbar__link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-color-secondary);
  font-size: var(--text-sm);
  font-weight: var(--font-weight-emphasis);
  cursor: pointer;
  white-space: nowrap;
  transition: background 150ms ease, color 150ms ease;
  position: relative;
}
.navbar__link:hover {
  background: var(--surface-hover);
  color: var(--text-color);
}
/* Fondo tenue del tono + texto del tono. Pintar el texto con «--primary-color»
   -que es el color de RELLENO- sobre su propio relleno claro es el par que el
   capitulo 8 prohibe. */
.navbar__link--active {
  background: var(--primary-color-light);
  color: var(--primary-color-text);
}

.navbar__icon { font-size: var(--text-sm); }

/* Actions */
.navbar__actions {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-left: auto;
}

/* Mobile toggle */
.navbar__mobile-toggle {
  display: none;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-color);
  cursor: pointer;
  font-size: var(--text-lg);
  margin-left: auto;
}

/* Mobile menu */
.navbar__mobile-menu {
  display: none;
  padding: var(--space-2) var(--space-4) var(--space-4);
  background: var(--surface-background);
  border-bottom: 1px solid var(--border-color);
}
.navbar__mobile-menu ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--space-1); }

.navbar__mobile-link {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  width: 100%;
  padding: var(--space-2) var(--space-3);
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-color-secondary);
  font-size: var(--text-sm);
  text-align: left;
  cursor: pointer;
  transition: background 150ms ease;
}
.navbar__mobile-link:hover,
.navbar__mobile-link--active {
  background: var(--primary-color-light);
  color: var(--primary-color-text);
}

/* Responsive */
@media (max-width: 48rem) {
  .navbar__nav { display: none; }
  .navbar__actions { display: none; }
  .navbar__mobile-toggle { display: flex; }
  .navbar__mobile-menu { display: block; }
}

