.pagination-wrapper {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  width: 100%;
  background-color: var(--pagination-wrapper-bg);
  border: 1px solid var(--pagination-wrapper-border);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xs);
}

.pagination-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-3);
  padding-bottom: var(--space-2);
  border-bottom: 1px solid var(--pagination-wrapper-border);
}

.info-text {
  font-size: var(--text-sm);
  color: var(--text-color-secondary);
}

.info-text strong {
  color: var(--pagination-accent-text);
  font-weight: var(--font-weight-title);
}

.page-size-selector {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.page-size-control {
  --select2-min-width: var(--pagination-page-size-inline-size);
  inline-size: var(--pagination-page-size-inline-size);
  flex: 0 0 var(--pagination-page-size-inline-size);
}

.page-size-selector label {
  font-size: var(--text-sm);
  color: var(--text-color-secondary);
}

.page-size-select {
  height: var(--control-height-sm);
  padding: 0 var(--space-2);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: var(--surface-background);
  color: var(--text-color);
  font-size: var(--text-sm);
  cursor: pointer;
  outline: none;
  transition: all 150ms ease;
}

.page-size-select:focus,
.page-size-select:hover {
  border-color: var(--primary-color);
}

.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-1);
}

/* En móvil con muchas páginas, el nav hace scroll horizontal */
@media (max-width: 40rem) {
  :host {
    display: block;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    padding-bottom: var(--space-1); /* Espacio para la barra de scroll */
  }

  .pagination {
    width: max-content; /* Evita que el flex container comprima los botones */
    min-width: 100%;
  }

  .page-btn,
  .page-ellipsis {
    flex-shrink: 0;
  }

  .pagination-info {
    align-items: stretch;
  }

  .page-size-selector {
    inline-size: 100%;
    justify-content: space-between;
  }

  .page-minimal-text {
    white-space: nowrap;
  }
}

.page-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: var(--control-height-sm);
  height: var(--control-height-sm);
  padding: 0 var(--space-2);
  background-color: var(--pagination-bg);
  border: 1px solid var(--pagination-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xs);
  font-size: var(--text-sm);
  font-weight: var(--font-weight-emphasis);
  color: var(--pagination-text);
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease, box-shadow 150ms ease;
}

.page-prev:not(:disabled),
.page-next:not(:disabled) {
  color: var(--pagination-accent-text);
  border-color: var(--pagination-badge-border);
}

.pagination-sm .page-btn {
  min-width: 1.75rem;
  height: 1.75rem;
  font-size: var(--text-xs);
}

.pagination-lg .page-btn {
  min-width: 2.5rem;
  height: 2.5rem;
  font-size: var(--text-md);
}

.page-btn:hover:not(:disabled):not(.active) {
  background-color: var(--pagination-hover-bg);
  border-color: var(--pagination-hover-border);
  color: var(--pagination-hover-text);
}

.page-btn:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus-primary);
}

.page-btn:disabled {
  background-color: var(--pagination-disabled-bg);
  border-color: var(--pagination-border);
  color: var(--pagination-disabled-text);
  box-shadow: none;
  cursor: not-allowed;
}

.page-btn.active {
  background-color: var(--pagination-active-bg);
  border-color: var(--pagination-active-border);
  color: var(--pagination-active-text);
  font-weight: var(--font-weight-title);
  box-shadow: var(--pagination-active-shadow);
}

.page-ellipsis {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--control-height-sm);
  color: var(--pagination-accent-text);
  font-size: var(--text-sm);
  font-weight: var(--font-weight-title);
}

/* Minimal Variant */
.pagination-minimal {
  justify-content: space-between;
  width: 100%;
  gap: var(--space-4);
}

.page-text-btn {
  padding: 0 var(--space-4);
  background-color: var(--pagination-bg);
  border: 1px solid var(--pagination-badge-border);
  color: var(--pagination-accent-text);
  font-weight: var(--font-weight-title);
  min-width: auto;
}

.page-text-btn:hover:not(:disabled) {
  background-color: var(--pagination-active-bg);
  border-color: var(--pagination-active-border);
  color: var(--pagination-active-text);
  box-shadow: var(--pagination-active-shadow);
}

.page-icon--start {
  margin-inline-end: var(--space-2);
}

.page-icon--end {
  margin-inline-start: var(--space-2);
}

.page-minimal-text {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  background-color: var(--pagination-badge-bg);
  border: 1px solid var(--pagination-badge-border);
  font-size: var(--text-sm);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color-secondary);
}

.page-minimal-text strong {
  color: var(--pagination-accent-text);
  font-weight: var(--font-weight-title);
}

/* Rounded Variant */
.pagination-rounded {
  background-color: var(--pagination-bg);
  border: 1px solid var(--pagination-border);
  border-radius: var(--radius-full);
  padding: var(--space-1) var(--space-2);
  width: fit-content;
  margin-inline: auto;
  box-shadow: var(--shadow-xs);
}

.pagination-rounded .page-btn {
  border-radius: var(--radius-full);
  border: 1px solid transparent;
  background-color: transparent;
  box-shadow: none;
}

.pagination-rounded .page-prev:not(:disabled),
.pagination-rounded .page-next:not(:disabled) {
  background-color: var(--pagination-badge-bg);
  border-color: var(--pagination-badge-border);
  color: var(--pagination-accent-text);
}

.pagination-rounded .page-btn:disabled {
  background-color: transparent;
  border-color: transparent;
  color: var(--pagination-disabled-text);
  box-shadow: none;
}

.pagination-rounded .page-btn:hover:not(:disabled):not(.active) {
  background-color: var(--pagination-hover-bg);
  border-color: var(--pagination-hover-border);
  color: var(--pagination-hover-text);
}

.pagination-rounded .page-btn.active {
  background-color: var(--pagination-active-bg);
  border-color: var(--pagination-active-border);
  color: var(--pagination-active-text);
  box-shadow: var(--pagination-active-shadow);
}

/* Cards Variant */
.pagination-cards {
  background-color: transparent;
  gap: var(--space-2);
}

.pagination-cards .page-btn {
  border-radius: var(--radius-md);
  border-width: 1px 1px 2px 1px;
  border-style: solid;
  border-color: var(--pagination-border);
  border-bottom-color: var(--pagination-card-accent-border);
  box-shadow: var(--shadow-sm);
  background-color: var(--pagination-bg);
  font-weight: var(--font-weight-title);
}

.pagination-cards .page-btn:disabled {
  background-color: var(--pagination-disabled-bg);
  border-color: var(--pagination-border);
  border-bottom-width: 1px;
  color: var(--pagination-disabled-text);
  box-shadow: none;
}

.pagination-cards .page-btn.active {
  background-color: var(--pagination-card-active-bg);
  border-color: var(--pagination-card-active-border);
  border-bottom-width: 2px;
  box-shadow: var(--pagination-active-shadow);
  color: var(--pagination-active-text);
}

/*
