@for (popup of popupService.popups(); track popup.id) {
  <div
    class="popup-overlay"
    [class.popup-closing]="popup.closing"
    (click)="onBackdropClick(popup)"
    (keydown.escape)="onEscape(popup, $event)"
    tabindex="0"
    role="dialog"
    aria-modal="true"
    [attr.aria-labelledby]="'popup-title-' + popup.id"
