      (keydown)="onPopupKeydown($event, popup)"
      tabindex="-1"
    >
      <!-- Header -->
      <div class="popup-header">
        @if (popup.icon) {
          <span class="popup-icon" [class]="'popup-icon-' + popup.type">
            <i [class]="popup.icon"></i>
          </span>
        }
        <h3 class="popup-title" [id]="'popup-title-' + popup.id">{{ popup.title }}</h3>
        @if (popup.closable) {
          <app-icon-button class="popup-close" (clicked)="onDismiss(popup)" ariaLabel="Cerrar" variant="hanging-close" animation="none">
          </app-icon-button>
        }
      </div>

      <!-- Body -->
      <app-scroll-overlay
        class="so-block popup-body-scroll"
        [skipTableDetection]="true"
        [disableHorizontal]="true"
      >
        <div class="popup-body">
          @if (popup.message) {
            <p class="popup-message">{{ popup.message }}</p>
          }
          @if (popup.htmlContent) {
            <div [innerHTML]="popup.htmlContent"></div>
          }
        </div>
      </app-scroll-overlay>

      <!-- Footer -->
      @if (popup.buttons && popup.buttons.length > 0) {
        <div class="popup-footer">
          @for (button of popup.buttons; track button.label) {
            <app-button
              class="popup-btn"
              [variant]="button.variant || 'primary'"
              [attr.data-autofocus]="button.autofocus ? '' : null"
              (buttonClick)="button.action()"
            >
              {{ button.label }}
            </app-button>
          }
        </div>
      }
    </div>
  </div>
}

