app-print-document-panel,
prest-print-document-panel {
  display: block;
  min-width: 0;
}

.print-document-panel {
  display: grid;
  gap: var(--space-4);
  min-width: 0;
  color: var(--text-color);
}

.print-document-panel__header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}

.print-document-panel__header h2,
.print-document-panel__header p,
.print-document-panel__page h3,
.print-document-panel__page h4,
.print-document-panel__page p {
  margin: 0;
}

.print-document-panel__header p,
.print-document-panel__subtitle,
.print-document-panel__table-summary {
  color: var(--text-color-muted);
  font-size: var(--text-sm);
}

.print-document-panel__actions,
app-print-document-panel [print-document-actions],
prest-print-document-panel [print-document-actions] {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.print-document-panel__pages {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: var(--space-3);
}

.print-document-panel__page {
  display: grid;
  align-content: start;
  gap: var(--space-3);
  min-width: 0;
  padding: var(--space-4);
  border: 1px solid var(--print-document-border);
  border-radius: var(--radius-lg);
  background: var(--print-document-background);
  box-shadow: var(--print-document-shadow);
}

.print-document-panel__eyebrow {
  color: var(--print-document-accent);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-title);
  letter-spacing: var(--letter-spacing-wide);
  text-transform: uppercase;
}

.print-document-panel__fields {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 10rem), 1fr));
  gap: var(--space-2);
  margin: 0;
}

.print-document-panel__fields div {
  min-width: 0;
  padding: var(--space-2);
  border-radius: var(--radius-md);
  background: var(--print-document-detail-background);
}

.print-document-panel__fields dt {
  color: var(--text-color-muted);
  font-size: var(--text-xs);
}

.print-document-panel__fields dd {
  margin: 0;
  overflow-wrap: anywhere;
  font-weight: var(--font-weight-emphasis);
}

.print-document-panel__section {
  display: grid;
  gap: var(--space-2);
  padding-top: var(--space-2);
  border-top: 1px solid var(--print-document-border);
}

.print-document-panel__signatures {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 10rem), 1fr));
  gap: var(--space-4);
  padding-top: var(--space-5);
}

.print-document-panel__signatures span {
  border-top: 1px solid var(--print-document-border);
  padding-top: var(--space-2);
  color: var(--text-color-muted);
  text-align: center;
}

.print-document-panel__footer {
  padding-top: var(--space-2);
  border-top: 1px solid var(--print-document-border);
  color: var(--text-color-muted);
  font-size: var(--text-xs);
}

@media (max-width: 36rem) {
  .print-document-panel__header,
  .print-document-panel__actions,
  app-print-document-panel [print-document-actions],
  prest-print-document-panel [print-document-actions] {
    align-items: stretch;
    flex-direction: column;
  }
}

