} from '@shared/ui';

@Component({
  selector: 'app-reports-page',
  standalone: true,
  imports: [
    LayoutShellComponent,
    TopbarComponent,
    SidebarComponent,
    PanelComponent,
    RowComponent,
    TextComponent,
    ButtonComponent,
    ThemeSwitcherComponent
  ],
  template: `
    <app-layout-shell [sidebarVisible]="sidebarVisible()" (closeSidebar)="sidebarVisible.set(false)">
      <app-sidebar ngProjectAs="[slot=sidebar]" slot="sidebar" [menuItems]="menuItems" logoText="Atomic UI" logoIcon="fa-solid fa-sack-dollar" logoIconColor="var(--purple-500)" logoTextColor="var(--text-color)" headerBgColor="var(--surface-sunken)" footerBgColor="var(--surface-sunken)" [user]="{ name: 'Usuario Demo', role: 'Administrador', initials: 'UD' }" (navigate)="onNavigate($event)"></app-sidebar>
      <app-topbar ngProjectAs="[slot=topbar]" [showHomeButton]="true" apiStatus="API en línea" [showUserInfo]="false" [showSidebarToggle]="true" slot="topbar" title="Reportes" [userName]="'Usuario'" (toggleSidebar)="sidebarVisible.set(!sidebarVisible())">
        <app-theme-switcher></app-theme-switcher>
      </app-topbar>

      <app-row justify="between" align="center" class="mb-6">
        <div>
          <app-text variant="h2" weight="bold">Generación de Reportes</app-text>
          <app-text variant="body" color="muted">Descarga y analiza información histórica</app-text>
        </div>
        <app-button variant="primary" iconClass="fa-solid fa-file-circle-plus">Nuevo Reporte</app-button>
      </app-row>

      <app-row columns="1fr" gap="1.5rem">
        <app-panel title="Reportes Generados Recientemente">
          <app-row columns="1fr" gap="1rem">
            @for (report of reports; track report.id) {
