import {
  Component,
  ElementRef,
  inject,
  PLATFORM_ID,
  input,
  output
} from '@angular/core';
import { isPlatformBrowser, NgTemplateOutlet } from '@angular/common';
import { AvatarComponent } from '../../atoms/avatar/avatar.component';
import { ScrollOverlayComponent } from '../scroll-overlay/scroll-overlay.component';
import { VariablesCssDirective } from '../../directives/variables-css.directive';
import { TooltipDirective } from '../../atoms/tooltip/tooltip.directive';

export interface SidebarMenuItem {
  id?: string;
  label: string;
  icon: string;
  iconColor?: string;
  active?: boolean;
  route?: string;
  badge?: string | number;
  children?: SidebarMenuItem[];
  expanded?: boolean;
  separator?: boolean;
}

export interface SidebarUser {
  name: string;
  role: string;
  initials?: string;
  photo?: string;
  avatarColor?: string;
}

@Component({
  selector: 'app-sidebar',
  standalone: true,
  imports: [AvatarComponent, NgTemplateOutlet, ScrollOverlayComponent, VariablesCssDirective, TooltipDirective],
  templateUrl: './sidebar.component.html',
  styleUrl: './sidebar.component.css',
})
export class SidebarComponent {
  private readonly platformId = inject(PLATFORM_ID);
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);

  /** Menu items to display */
  readonly menuItems = input<SidebarMenuItem[]>([]);

  /** Current user information */
  readonly user = input<SidebarUser | null>();

  /** Check if the sidebar is expanded (visual mode) */
  readonly collapsed = input(false);

  /** Logo text */
  readonly logoText = input('Atomic UI');

  /** Logo icon */
  readonly logoIcon = input('fa-solid fa-atom');

  /** Logo icon color */
  readonly logoIconColor = input<string>();

  /** Logo text color */
  readonly logoTextColor = input<string>();

  /** Background color for the header (logo area) */
  readonly headerBgColor = input<string>();

  /** Background color for the footer (user area) */
  readonly footerBgColor = input<string>();

  /** Event emitted when a menu item is clicked */
  readonly navigate = output<SidebarMenuItem>();

  private readonly expansionOverrides = new Map<string, boolean>();

  onItemClick(item: SidebarMenuItem): void {
    if (this.hasChildren(item)) {
      this.expansionOverrides.set(this.itemKey(item), !this.isExpanded(item));
      return;
    }
    this.navigate.emit(item);
  }

  hasChildren(item: SidebarMenuItem): boolean {
    return (item.children?.length ?? 0) > 0;
  }

  isExpanded(item: SidebarMenuItem): boolean {
    const override = this.expansionOverrides.get(this.itemKey(item));
    if (override !== undefined) {
      return override;
    }
    return item.expanded ?? this.containsActiveItem(item);
  }

  itemKey(item: SidebarMenuItem): string {
    return item.id ?? item.route ?? item.label;
  }

  handleKeydown(event: KeyboardEvent): void {
    if (!isPlatformBrowser(this.platformId)) return;

    const items = Array.from(
      this.host.nativeElement.querySelectorAll<HTMLElement>('.sidebar-nav .nav-link'),
    );
    if (!items.length) return;

    const activeIndex = Math.max(
      items.indexOf(this.host.nativeElement.ownerDocument.activeElement as HTMLElement),
      0,
    );
    let nextIndex: number | undefined;

    switch (event.key) {
      case 'ArrowDown':
        nextIndex = (activeIndex + 1) % items.length;
        break;
      case 'ArrowUp':
        nextIndex = (activeIndex - 1 + items.length) % items.length;
        break;
      case 'Home':
        nextIndex = 0;
        break;
      case 'End':
        nextIndex = items.length - 1;
        break;
    }

    if (nextIndex !== undefined) {
      items[nextIndex]?.focus();
      event.preventDefault();
    }
  }

  private containsActiveItem(item: SidebarMenuItem): boolean {
    return !!item.active || !!item.children?.some((child) => this.containsActiveItem(child));
  }
}

