import {
  Component,
  computed,
  forwardRef,
  signal,
  ChangeDetectionStrategy,
  input,
  output
} from '@angular/core';

import { ControlValueAccessor, NG_VALUE_ACCESSOR, FormsModule } from '@angular/forms';
import { ChipComponent } from '../../atoms/chip/chip.component';
import {
  FIELD_LABEL_VARIANT_DEFAULT,
  FieldLabelVariant,
  esEtiquetaElevada,
  esEtiquetaFlotante,
  esMarcadorVisible,
} from '../../atoms/form-field/field-label';

export interface TagInputOption {
  label: string;
  value: string;
}

/**
 * TagInputComponent — Campo de entrada con etiquetas/chips removibles.
 * Compatible con `ngModel` y `FormControl`.
 *
 * @example
 * ```html
 * <app-tag-input
 *   [(ngModel)]="tags"
 *   label="Etiquetas"
 *   placeholder="Escribe y presiona Enter"
 *   [maxTags]="5"
 * ></app-tag-input>
 * ```
 */
@Component({
  selector: 'app-tag-input',
  standalone: true,
  imports: [FormsModule, ChipComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => TagInputComponent),
      multi: true,
    },
  ],
  template: `
    <div
      class="tag-input-wrapper fl-field"
      [class.fl-field--floating]="flotante()"
      [class.tag-input--elevated]="elevada()"
      [class.tag-input--has-tags]="tags().length > 0"
      [class.tag-input--disabled]="isDisabled()"
      [class.tag-input--focused]="focused()"
      [class.tag-input--error]="error()"
    >
      @if (label() && !flotante()) {
        <label
          class="fl-label tag-input__label"
          [class.fl-label--error]="error()"
          [class.fl-label--disabled]="isDisabled()"
          [for]="inputId"
        >
          {{ label() }}
          @if (required()) {
            <span class="field__required fl-label__required" aria-hidden="true">*</span>
          }
        </label>
      }
      <div class="fl-control tag-input__field">
        @if (flotante()) {
          <label
            class="fl-label fl-label--floating"
            [class.fl-label--floated]="elevada()"
            [class.fl-label--error]="error()"
            [class.fl-label--disabled]="isDisabled()"
            [for]="inputId"
          >
            {{ label() }}
            @if (required()) {
              <span class="field__required fl-label__required" aria-hidden="true">*</span>
            }
          </label>
        }
        <!-- Tags -->
        @for (tag of tags(); track tag) {
          <app-chip
            size="sm"
            variant="primary"
            [removable]="!isDisabled()"
            (remove)="removeTag(tag)"
          >{{ tag }}</app-chip>
        }

        <!-- Input -->
        @if (maxTags() === null || tags().length < (maxTags() ?? 0)) {
          <input
            #inputEl
            [id]="inputId"
            class="tag-input__input"
            [attr.placeholder]="tags().length === 0 ? marcador() : null"
            [attr.aria-required]="required() ? 'true' : null"
            [disabled]="isDisabled()"
            [(ngModel)]="inputValue"
            (keydown)="onKeydown($event)"
            (focus)="focused.set(true)"
            (blur)="onBlur()"
            [attr.aria-label]="label() || placeholder()"
          />
        }
      </div>

      @if (hint()) {
        <span class="tag-input__hint">{{ hint() }}</span>
      }
      @if (error()) {
        <span class="tag-input__error">{{ error() }}</span>
      }
    </div>
  `,
  styleUrls: ['./tag-input.component.css', '../../atoms/form-field/field-label.css'],
})
export class TagInputComponent implements ControlValueAccessor {
  readonly inputId = 'tag-input-' + Math.random().toString(36).slice(2, 8);

  readonly label = input('');
  /** Modo de etiqueta comun: standard | floating | floating-value. */
  readonly variant = input<FieldLabelVariant>(FIELD_LABEL_VARIANT_DEFAULT);
  readonly placeholder = input('Agregar etiqueta…');
  readonly hint = input('');
  readonly error = input('');
  readonly required = input(false);
  readonly maxTags = input<number | null>(null);
  readonly allowDuplicates = input(false);
  readonly disabled = input(false);
  private readonly disabledByForm = signal(false);

  isDisabled(): boolean {
    return this.disabled() || this.disabledByForm();
  }
  readonly separator = input<string[]>(['Enter', ',']);

  readonly tagAdded = output<string>();
  readonly tagRemoved = output<string>();

  protected tags = signal<string[]>([]);
  protected focused = signal(false);
  /** Texto en edicion: senal, para que la etiqueta flotante reaccione mientras se escribe. */
  private readonly textoEscrito = signal('');
  protected get inputValue(): string {
    return this.textoEscrito();
  }
  protected set inputValue(valor: string) {
    this.textoEscrito.set(valor);
  }

  protected readonly tieneEtiqueta = computed(() => this.label().length > 0);
  protected readonly flotante = computed(() =>
    esEtiquetaFlotante(this.variant(), this.tieneEtiqueta()),
  );
  protected readonly elevada = computed(() =>
    esEtiquetaElevada(
      this.variant(),
      this.tieneEtiqueta(),
      this.focused(),
      this.tags().length > 0 || this.textoEscrito().length > 0,
    ),
  );
  protected readonly marcador = computed(() =>
    esMarcadorVisible(this.variant(), this.tieneEtiqueta(), this.elevada())
      ? this.placeholder() || null
      : null,
  );

  private onChange: (value: string[]) => void = () => {};
  private onTouched: () => void = () => {};

  writeValue(value: string[]): void {
    this.tags.set(Array.isArray(value) ? value : []);
  }

  registerOnChange(fn: (value: string[]) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabledByForm.set(isDisabled);
  }

  onKeydown(event: KeyboardEvent): void {
    if (this.separator().includes(event.key)) {
      event.preventDefault();
      this.addTag();
    } else if (event.key === 'Backspace' && !this.inputValue && this.tags().length) {
      const current = this.tags();
      this.removeTag(current[current.length - 1]);
    }
  }

  onBlur(): void {
    this.focused.set(false);
    if (this.inputValue.trim()) {
      this.addTag();
    }
    this.onTouched();
  }

  private addTag(): void {
    const value = this.inputValue.trim().replace(/,$/, '');
    if (!value) return;
    if (!this.allowDuplicates() && this.tags().includes(value)) {
      this.inputValue = '';
      return;
    }
    const maxTags = this.maxTags();
    if (maxTags && this.tags().length >= maxTags) return;

    const newTags = [...this.tags(), value];
    this.tags.set(newTags);
    this.inputValue = '';
    this.onChange(newTags);
    this.tagAdded.emit(value);
  }

  removeTag(tag: string): void {
    const newTags = this.tags().filter(t => t !== tag);
    this.tags.set(newTags);
    this.onChange(newTags);
    this.tagRemoved.emit(tag);
  }
}

styleUrlsData.data:
:host { display: block; width: 100%; }

/* La tipografia de la etiqueta (superior y flotante) vive en ../../atoms/form-field/field-label.css */
.tag-input__field {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1);
  box-sizing: border-box;
  min-height: var(--control-height);
  padding: var(--space-2) var(--space-4);
  border: var(--border-width-thin) solid var(--input-border);
  border-radius: var(--radius-md);
  background: var(--input-bg);
  box-shadow: var(--input-shadow);
  cursor: text;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.fl-field--floating.tag-input--elevated.tag-input--has-tags .tag-input__field {
  padding-top: var(--space-4);
  padding-bottom: var(--space-2);
}

.tag-input-wrapper:not(.tag-input--disabled):not(.tag-input--focused) .tag-input__field:hover {
  border-color: var(--input-border-hover);
  box-shadow: var(--input-shadow-hover);
}

.tag-input--focused .tag-input__field {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.tag-input--error .tag-input__field {
  border-color: var(--danger-color);
}

.tag-input--disabled .tag-input__field {
  cursor: not-allowed;
  background: var(--input-disabled-bg);
  color: var(--input-disabled-text);
  box-shadow: none;
}

.tag-input__input {
  flex: 1;
  min-width: 5rem;
  border: none;
  outline: none;
  box-shadow: none;
  background: transparent;
  font-family: inherit;
  font-size: var(--text-md);
  font-weight: var(--font-weight-body);
  line-height: var(--field-label-line-height);
  color: var(--text-color);
  padding: 0;
}

.tag-input__input:focus,
.tag-input__input:focus-visible {
  border: none;
  outline: none;
  box-shadow: none;
}

.tag-input__input::placeholder {
  color: var(--input-placeholder);
}

.tag-input--disabled .tag-input__input {
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

.tag-input__hint {
  display: block;
  font-size: var(--text-xs);
  color: var(--text-color-muted);
}

.tag-input__error {
  display: block;
  font-size: var(--text-xs);
  color: var(--danger-color-text);
}

/*
  Estilos compartidos de la etiqueta de campo (contrato `variant`: standard | floating | floating-value).

  Se incluyen en cada control con `styleUrls: ['./x.css', '../form-field/field-label.css']`, de modo
  que la tipografia, el color y la geometria de la etiqueta salen de UN solo lugar y de tokens
  `--field-label-*`: nada de rem literales ni `uppercase` en los controles.

  Geometria de la etiqueta flotante
  ---------------------------------
  `.fl-control` es la CAJA del control y solo contiene el control. La ayuda y el error viven FUERA
  de ella. Si la etiqueta se anclara al contenedor que tambien lleva la ayuda, `top: 50%` caeria
  en el centro de caja + ayuda y la etiqueta quedaria desplazada hacia abajo cuando hay mensaje.

  - Reposo:  centrada en la mitad de `--control-height` (primera linea en controles multilinea).
  - Elevada: centrada sobre el borde superior (`top: 0` + `translateY(-50%)`), con el fondo del
             campo recortando el borde. Como el centrado es relativo al propio texto, no depende
             del tamano de fuente.
*/

.fl-field {
  display: grid;
  min-width: 0;
  gap: var(--field-label-gap);
}

/* Reserva el espacio que ocupa la etiqueta elevada sobre el borde superior del control. */
.fl-field--floating {
  margin-top: var(--space-3);
}

/* El mensaje de error lo dibuja app-form-error: la rejilla ya separa, asi que no suma su propio margen. */
.fl-field > app-form-error {
  --form-error-gap: 0;
}

.fl-control {
  position: relative;
  min-width: 0;
}

/* Etiqueta superior (variant="standard"). */
.fl-label {
  display: block;
  color: var(--field-label-color);
  font-size: var(--field-label-font-size);
  font-weight: var(--field-label-font-weight);
  line-height: var(--field-label-line-height);
}

.field__required,
.fl-label__required {
  color: var(--field-label-color-error);
}

/* Etiqueta flotante (variant="floating" | "floating-value"): reposo. */
.fl-label--floating {
  position: absolute;
  top: calc(var(--control-height) / 2);
  left: var(--field-label-inset);
  z-index: 1;
  max-width: calc(100% - var(--field-label-inset) - var(--space-1));
  overflow: hidden;
  padding: var(--field-label-padding);
