:host {
  display: block;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  background-color: var(--surface-background);
  border-bottom: 1px solid var(--border-color);
  transition: background-color 0.3s ease, border-color 0.3s ease;
}

.topbar-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 0 2.25rem;
  gap: var(--space-4);
}

.topbar-left {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex: 1 1 0%;
  min-width: 0;
}

.topbar-title-area {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
}

.page-title {
  margin: 0;
  font-size: var(--text-lg, 1.125rem);
  font-weight: bold;
  color: var(--text-color);
  line-height: 1.2;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.topbar-subtitle-row {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-top: 0.125rem;
}

.page-subtitle {
  font-size: var(--text-xs);
  color: var(--text-color-secondary);
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.api-status-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: 0 var(--space-2);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-emphasis);
  border-radius: var(--radius-full);
  line-height: 1.4;
  white-space: nowrap;
}

.api-status-badge.badge-success { background-color: var(--success-color-light); color: var(--success-color-text); }
.api-status-badge.badge-warning { background-color: var(--warning-color-light); color: var(--warning-color-text); }
.api-status-badge.badge-danger { background-color: var(--danger-color-light); color: var(--danger-color-text); }

.status-dot {
  font-size: 0.375rem;
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  flex-shrink: 0;
  margin-left: auto;
}

.topbar-icon {
  font-size: var(--text-xl, 1.25rem);
}

@media (max-width: 48rem) {
  .topbar-container {
    padding: 0 2.25rem;
    gap: var(--space-2);
  }

  .topbar-left {
    gap: var(--space-2);
  }

  .page-title {
    font-size: var(--text-md);
  }

  .topbar-right {
    gap: var(--space-1);
  }

  .topbar-right ::ng-deep app-icon-button {
    transform: scale(0.9);
  }
}

@media (max-width: 35rem) {
  .topbar-right ::ng-deep app-language-switcher {
    display: none;
  }
}


/* Hide hamburger by default (desktop) */
.sidebar-toggle-wrapper {
  display: none;
}

/* Show hamburger on mobile/tablet */
@media (max-width: 64rem) {
  .sidebar-toggle-wrapper {
    display: block;
  }
}

.sidebar-toggle-wrapper ::ng-deep button, .sidebar-toggle-wrapper ::ng-deep app-icon-button { transform: none !important; }



/* === Notification Dropdown === */
.notification-dropdown-wrapper {
  position: relative;
}

.notification-dropdown {
  position: absolute;
  top: calc(100% + var(--space-2));
  right: -0.3125rem;
  width: 20rem;
  max-width: calc(100vw - var(--space-4));
  background: var(--surface-background);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  z-index: 1000;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.notification-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border-color);
  background: var(--surface-section);
}

.notification-title {
  font-weight: var(--font-weight-emphasis);
  font-size: var(--text-sm);
  color: var(--text-color);
}

.mark-read-btn {
  background: transparent;
  border: none;
  color: var(--primary-color);
  font-size: var(--text-xs);
  cursor: pointer;
  padding: 0;
}

.mark-read-btn:hover {
  text-decoration: underline;
}

.notification-list {
  display: flex;
  flex-direction: column;
}

.notification-empty {
  padding: var(--space-4);
  text-align: center;
  color: var(--text-color-secondary);
  font-size: var(--text-sm);
}

.notification-item {
  display: flex;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  cursor: pointer;
  border-bottom: 1px solid var(--border-color);
  transition: background 0.2s ease;
  position: relative;
}

.notification-item:last-child {
  border-bottom: none;
}

.notification-item:hover {
  background: var(--surface-hover);
}

.notification-item.unread {
  background: var(--surface-hover);
}

.notification-item.unread:hover {
  background: var(--surface-hover);
}

.notification-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--space-8);
  height: var(--space-8);
  border-radius: 50%;
  background: var(--surface-section);
  color: var(--primary-color);
  font-size: var(--text-lg);
  flex-shrink: 0;
}

.notification-content {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  flex: 1;
  min-width: 0;
}

.notification-item-title {
  font-size: var(--text-sm);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.notification-item-message {
  font-size: var(--text-xs);
  color: var(--text-color-secondary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.notification-item-time {
  font-size: var(--text-2xs);
  color: var(--text-color-muted);
  margin-top: 0.125rem;
}

.notification-unread-dot {
  width: var(--space-2);
  height: var(--space-2);
  background-color: var(--primary-color);
  border-radius: 50%;
  position: absolute;
  right: var(--space-4);
  top: 50%;
  transform: translateY(-50%);
}

