/*
  El anfitrion de una historia es un elemento a medida y por omision es
  «inline»: sin esto, la plantilla no ocupa el ancho del lienzo y lo que se
  revisa no es la disposicion real.
*/
:host {
  display: block;
}

.crud {
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
  min-height: 100dvh;
  padding: var(--space-6);
  box-sizing: border-box;
  background-color: var(--surface-background);
}

.crud__filtro {
  flex: 1 1 14rem;
  min-width: 0;
}

.crud__seleccion {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  padding: var(--space-3) var(--space-4);
  border: var(--border-width-thin) solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: var(--surface-section);
}

.crud__seleccion-texto {
  margin: 0;
  font-size: var(--text-sm);
}

.crud__seleccion-acciones {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
}

/*
  Cifras de ancho fijo: documentos y saldos apilados solo se comparan de un
  vistazo si cada digito ocupa lo mismo.
*/
.crud__cifra,
.crud__col-cifra {
  font-variant-numeric: tabular-nums;
}

.crud__col-cifra {
  text-align: right;
}

.crud__caption {
  padding-block-end: var(--space-3);
  font-size: var(--text-sm);
  text-align: left;
}

.crud__acciones-fila {
  display: flex;
  flex-wrap: nowrap;
  gap: var(--space-1);
}

.crud__vacio {
  margin: 0;
  padding: var(--space-6) var(--space-4);
  font-size: var(--text-sm);
  text-align: center;
}

.crud__confirmacion-texto {
  margin: 0 0 var(--space-3);
  font-size: var(--text-sm);
}

.crud__confirmacion-lista {
  margin: 0 0 var(--space-4);
  padding-inline-start: var(--space-5);
  font-size: var(--text-sm);
}

.crud__confirmacion-acciones {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--space-3);
}

