`
  @page {
    size: A4 portrait;
    margin: 15mm;
  }

  * {
    box-sizing: border-box;
  }

  html,
  body {
    margin: 0;
    padding: 0;
    background: var(--print-document-paper-background);
    color: var(--print-document-paper-color);
    font-family: var(--print-document-font-family, Arial, sans-serif);
    font-size: 10pt;
    line-height: 1.4;
  }

  .print-page {
    break-after: page;
    min-height: 260mm;
  }

  .print-page:last-child {
    break-after: auto;
  }

  .eyebrow,
  .subtitle,
  .footer {
    color: var(--print-document-muted-color);
  }

  .eyebrow {
    margin: 0 0 2mm;
    font-size: 8pt;
    font-weight: var(--font-weight-title);
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  h1 {
    margin: 0;
    color: var(--print-document-accent-color);
    font-size: 18pt;
  }

  h2 {
    margin: 7mm 0 3mm;
    font-size: 12pt;
  }

  .subtitle {
    margin: 2mm 0 6mm;
  }

  dl {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 2mm 6mm;
    margin: 4mm 0;
  }

  dl div {
    border-bottom: 0.2mm solid var(--print-document-border-color);
    padding: 1.5mm 0;
  }

  dt {
    color: var(--print-document-muted-color);
    font-size: 8pt;
    font-weight: var(--font-weight-title);
    text-transform: uppercase;
  }

  dd {
    margin: 1mm 0 0;
    overflow-wrap: anywhere;
    font-weight: var(--font-weight-emphasis);
  }

  p {
    margin: 0 0 3mm;
    text-align: justify;
  }

  table {
    width: 100%;
    margin-top: 3mm;
    border-collapse: collapse;
    font-size: 8pt;
  }

  caption {
    margin-bottom: 2mm;
    font-weight: var(--font-weight-title);
    text-align: left;
  }

  th,
  td {
    border: 0.2mm solid var(--print-document-border-color);
    padding: 1.4mm;
    vertical-align: top;
  }

  th {
    background: color-mix(
      in srgb,
      var(--print-document-border-color) 45%,
      var(--print-document-paper-background)
    );
    text-align: left;
  }

  .align-center {
    text-align: center;
  }

  .align-end {
    text-align: right;
  }

  .signatures {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 18mm;
    margin-top: 24mm;
  }

  .signature {
    border-top: 0.3mm solid var(--print-document-paper-color);
    padding-top: 2mm;
    text-align: center;
  }

  .footer {
    margin-top: 8mm;
    border-top: 0.2mm solid var(--print-document-border-color);
    padding-top: 2mm;
    font-size: 8pt;
  }
`

